 Control","tactic":"privilege-escalation"},{"id":"T1553.005","name":"Mark-of-the-Web Bypass","tactic":"defense-impairment"},{"id":"T1561.002","name":"Disk Structure Wipe","tactic":"impact"},{"id":"T1565.001","name":"Stored Data Manipulation","tactic":"impact"},{"id":"T1565.002","name":"Transmitted Data Manipulation","tactic":"impact"},{"id":"T1565.003","name":"Runtime Data Manipulation","tactic":"impact"},{"id":"T1566.001","name":"Spearphishing Attachment","tactic":"initial-access"},{"id":"T1569.002","name":"Service Execution","tactic":"execution"},{"id":"T1583.001","name":"Domains","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1685","name":"Disable or Modify Tools","tactic":"defense-impairment"},{"id":"T1685.005","name":"Clear Windows Event Logs","tactic":"defense-impairment"},{"id":"T1686","name":"Disable or Modify System Firewall","tactic":"defense-impairment"},{"id":"T1686.002","name":"Network Device Firewall","tactic":"defense-impairment"},{"id":"T1690","name":"Prevent Command History Logging","tactic":"defense-impairment"}]', '["DarkComet","ECCENTRICBANDWAGON","HOPLIGHT","KillDisk","Mimikatz","Net"]', '[]', '2019-01-29', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
