:"Scheduled Task","tactic":"execution"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1059.003","name":"Windows Command Shell","tactic":"execution"},{"id":"T1074.001","name":"Local Data Staging","tactic":"collection"},{"id":"T1078","name":"Valid Accounts","tactic":"stealth"},{"id":"T1090.002","name":"External Proxy","tactic":"command-and-control"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1133","name":"External Remote Services","tactic":"persistence"},{"id":"T1136.002","name":"Domain Account","tactic":"persistence"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1505.003","name":"Web Shell","tactic":"persistence"},{"id":"T1550.002","name":"Pass the Hash","tactic":"lateral-movement"},{"id":"T1553.002","name":"Code Signing","tactic":"defense-impairment"},{"id":"T1560.001","name":"Archive via Utility","tactic":"collection"},{"id":"T1570","name":"Lateral Tool Transfer","tactic":"lateral-movement"},{"id":"T1574.001","name":"DLL","tactic":"stealth"},{"id":"T1583.004","name":"Server","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"}]', '["BlackMould","China Chopper","HTRAN","Mimikatz","NBTscan","Net","Ping","PingPull","PlugX","PoisonIvy","PsExec","Reg","Windows Credential Editor","at","cmd","ipconfig"]', '[]', '2019-07-18', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
