INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G1049', 'applejeus', 'AppleJeus', '["UNC4736","UNC1720","Gleaming Pisces","Citrine Sleet"]', 'G1049', 'https://attack.mitre.org/groups/G1049', 'Unattributed / Mixed', '["Government"]', '[]', 'AppleJeus is a North Korean state-sponsored threat group attributed to the Reconnaissance General Bureau. Associated with the broader Lazarus Group umbrella of actors, AppleJeus has been active since at least 2018 and is closely aligned in resources with TEMP.hermit, another DPRK-affiliated group under the same umbrella. The group’s primary mission is to generate and launder revenue to provide financial support to the government. AppleJeus primarily targets the cryptocurrency industry and is most notably responsible for the 3CX Supply Chain Attack. The group traditionally deploys malicious cryptocurrency software in combination with Phishing. From these compromised environments, it selectively deploys additional backdoors to enable extended operations against high-value financial targets.', '[{"id":"T1566","name":"Phishing","tactic":"initial-access"},{"id":"T1657","name":"Financial Theft","tactic":"impact"}]', '[]', '[]', '2025-08-25', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
--> statement-breakpoint
INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G0018', 'admin-338', 'admin@338', '["admin@338"]', 'G0018', 'https://attack.mitre.org/groups/G0018', 'Financial / Ransomware', '[]', '[]', 'admin@338 is a China-based cyber threat group. It has previously used newsworthy events as lures to deliver malware and has primarily targeted organizations involved in financial, economic, and trade policy, typically using publicly available RATs such as PoisonIvy, as well as some non-public backdoors.', '[{"id":"T1007","name":"System Service Discovery","tactic":"discovery"},{"id":"T1016","name":"System Network Configuration Discovery","tactic":"discovery"},{"id":"T1036.005","name":"Match Legitimate Resource Name or Location","tactic":"stealth"},{"id":"T1049","name":"System Network Connections Discovery","tactic":"discovery"},{"id":"T1059.003","name":"Windows Command Shell","tactic":"execution"},{"id":"T1069.001","name":"Local Groups","tactic":"discovery"},{"id":"T1082","name":"System Information Discovery","tactic":"discovery"},{"id":"T1083","name":"File and Directory Discovery","tactic":"discovery"},{"id":"T1087.001","name":"Local Account","tactic":"discovery"},{"id":"T1203","name":"Exploitation for Client Execution","tactic":"execution"},{"id":"T1204.002","name":"Malicious File","tactic":"execution"},{"id":"T1566.001","name":"Spearphishing Attachment","tactic":"initial-access"}]', '["BUBBLEWRAP","LOWBALL","Net","PoisonIvy","Systeminfo","ipconfig","netstat"]', '["CVE-2012-0158"]', '2017-05-31', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
