INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G1017', 'volt-typhoon', 'Volt Typhoon', '["Vanguard Panda","DEV-0391","UNC3236","Voltzite","Insidious Taurus","DazedToad","BRONZE SILHOUETTE"]', 'G1017', 'https://attack.mitre.org/groups/G1017', 'Destructive / Hacktivism', '["Technology"]', '[]', 'Volt Typhoon is a People''s Republic of China (PRC) state-sponsored actor that has been active since at least 2021, primarily targeting critical infrastructure organizations in the US and its territories including Guam. Volt Typhoon''s targeting and pattern of behavior have been assessed as pre-positioning to enable lateral movement to operational technology (OT) assets for potential destructive or disruptive attacks. Volt Typhoon has emphasized stealth in operations using web shells, living-off-the-land (LOTL) binaries, hands on keyboard activities, and stolen credentials.. The group has leveraged compromised SOHO routers to proxy command and control traffic and obscure its infrastructure, activity associated with the KV botnet.. Reporting indicates a separate initial access cluster, SYLVANITE, has been observed exploiting internet-facing edge devices and transferring access to Volt Typhoon, also tracked as VOLTZITE, for follow-on operations.', '[{"id":"T1003.001","name":"LSASS Memory","tactic":"credential-access"},{"id":"T1003.003","name":"NTDS","tactic":"credential-access"},{"id":"T1005","name":"Data from Local System","tactic":"collection"},{"id":"T1006","name":"Direct Volume Access","tactic":"stealth"},{"id":"T1007","name":"System Service Discovery","tactic":"discovery"},{"id":"T1010","name":"Application Window Discovery","tactic":"discovery"},{"id":"T1012","name":"Query Registry","tactic":"discovery"},{"id":"T1016","name":"System Network Configuration Discovery","tactic":"discovery"