ic":"reconnaissance"},{"id":"T1593.003","name":"Code Repositories","tactic":"reconnaissance"},{"id":"T1685.005","name":"Clear Windows Event Logs","tactic":"defense-impairment"}]', '["ASPXSpy","China Chopper","Covenant","Impacket","PsExec","Tarrask"]', '[]', '2021-03-03', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
