id":"T1574.001","name":"DLL","tactic":"stealth"}]', '["Aria-body","HDoor","Nebulae","Net","Ping","PsExec","RARSTONE","RainyDay","SslMM","Sys10","Systeminfo","Tasklist","WinMM","ftp","netsh"]', '[]', '2017-05-31', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
