INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G0046', 'fin7', 'FIN7', '["Carbon Spider","FIN7","ELBRUS","Sangria Tempest","GOLD NIAGARA","ITG14"]', 'G0046', 'https://attack.mitre.org/groups/G0046', 'Financial / Ransomware', '["Retail","Transportation","Media"]', '["United States"]', 'FIN7 is a financially-motivated threat group that has been active since 2013. FIN7 has targeted the retail, restaurant, hospitality, software, consulting, financial services, medical equipment, cloud services, media, food and beverage, transportation, pharmaceutical, and utilities industries in the United States. A portion of FIN7 was operated out of a front company called Combi Security and often used point-of-sale malware for targeting efforts. Since 2020, FIN7 shifted operations to big game hunting (BGH), including use of REvil ransomware and their own Ransomware-as-a-Service (RaaS), Darkside. FIN7 may be linked to the Carbanak Group, but multiple threat groups have been observed using Carbanak, leading these groups to be tracked separately.', '[{"id":"T1005","name":"Data from Local System","tactic":"collection"},{"id":"T1008","name":"Fallback Channels","tactic":"command-and-control"},{"id":"T1021.001","name":"Remote Desktop Protocol","tactic":"lateral-movement"},{"id":"T1021.004","name":"SSH","tactic":"lateral-movement"},{"id":"T1021.005","name":"VNC","tactic":"lateral-movement"},{"id":"T1027.010","name":"Command Obfuscation","tactic":"stealth"},{"id":"T1027.016","name":"Junk Code Insertion","tactic":"stealth"},{"id":"T1033","name":"System Owner/User Discovery","tactic":"discovery"},{"id":"T1036.004","name":"Masquerade Task or Service","tactic":"stealth"},{"id":"T1036.005","name":"Match Legitimate Resource Name or Location","tactic":"stealth"},{"id":"T1047","name":"Windows Management Instrumen