INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G0034', 'sandworm-team', 'Sandworm Team', '["Voodoo Bear","ELECTRUM","Sandworm Team","Quedagh","FROZENBARENTS","APT44","IRIDIUM","Seashell Blizzard","BlackEnergy (Group)","Telebots","IRON VIKING"]', 'G0034', 'https://attack.mitre.org/groups/G0034', 'Espionage / State-Nexus', '["Government","Defense"]', '[]', 'Sandworm Team is a destructive threat group that has been attributed to Russia''s General Staff Main Intelligence Directorate (GRU) Main Center for Special Technologies (GTsST) military unit 74455. This group has been active since at least 2009. In October 2020, the US indicted six GRU Unit 74455 officers associated with Sandworm Team for the following cyber operations: the 2015 and 2016 attacks against Ukrainian electrical companies and government organizations, the 2017 worldwide NotPetya attack, targeting of the 2017 French presidential campaign, the 2018 Olympic Destroyer attack against the Winter Olympic Games, the 2018 operation against the Organisation for the Prohibition of Chemical Weapons, and attacks against the country of Georgia in 2018 and 2019. Some of these were conducted with the assistance of GRU Unit 26165, which is also referred to as APT28.', '[{"id":"T1003.001","name":"LSASS Memory","tactic":"credential-access"},{"id":"T1003.003","name":"NTDS","tactic":"credential-access"},{"id":"T1005","name":"Data from Local System","tactic":"collection"},{"id":"T1018","name":"Remote System Discovery","tactic":"discovery"},{"id":"T1021.002","name":"SMB/Windows Admin Shares","tactic":"lateral-movement"},{"id":"T1027","name":"Obfuscated Files or Information","tactic":"stealth"},{"id":"T1027.010","name":"Command Obfuscation","tactic":"stealth"},{"id":"T1033","name":"System Owner/User Discovery","tactic":"discovery"},{"id":