INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G0095', 'machete', 'Machete', '["Machete","APT-C-43","El Machete"]', 'G0095', 'https://attack.mitre.org/groups/G0095', 'Espionage / State-Nexus', '["Government","Telecom","Defense"]', '["Europe","Latin America"]', 'Machete is a suspected Spanish-speaking cyber espionage group that has been active since at least 2010. It has primarily focused its operations within Latin America, with a particular emphasis on Venezuela, but also in the US, Europe, Russia, and parts of Asia. Machete generally targets high-profile organizations such as government institutions, intelligence services, and military units, as well as telecommunications and power companies.', '[{"id":"T1036.005","name":"Match Legitimate Resource Name or Location","tactic":"stealth"},{"id":"T1053.005","name":"Scheduled Task","tactic":"execution"},{"id":"T1059.003","name":"Windows Command Shell","tactic":"execution"},{"id":"T1059.005","name":"Visual Basic","tactic":"execution"},{"id":"T1059.006","name":"Python","tactic":"execution"},{"id":"T1189","name":"Drive-by Compromise","tactic":"initial-access"},{"id":"T1204.001","name":"Malicious Link","tactic":"execution"},{"id":"T1204.002","name":"Malicious File","tactic":"execution"},{"id":"T1218.007","name":"Msiexec","tactic":"stealth"},{"id":"T1566.001","name":"Spearphishing Attachment","tactic":"initial-access"},{"id":"T1566.002","name":"Spearphishing Link","tactic":"initial-access"}]', '["Machete"]', '[]', '2019-09-13', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
