INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G0138', 'andariel', 'Andariel', '["Silent Chollima","Andariel","PLUTONIUM","Onyx Sleet"]', 'G0138', 'https://attack.mitre.org/groups/G0138', 'Financial / Ransomware', '["Government","Defense"]', '[]', 'Andariel is a North Korean state-sponsored threat group that has been active since at least 2009. Andariel has primarily focused its operations--which have included destructive attacks--against South Korean government agencies, military organizations, and a variety of domestic companies, they have also conducted cyber financial operations against ATMs, banks, and cryptocurrency exchanges. Andariel''s notable activity includes Operation Black Mine, Operation GoldenAxe, and Campaign Rifle. Andariel is considered a sub-set of Lazarus Group, and has been attributed to North Korea''s Reconnaissance General Bureau. North Korean group definitions are known to have significant overlap, and some security researchers report all North Korean state-sponsored cyber activity under the name Lazarus Group instead of tracking clusters or subgroups.', '[{"id":"T1005","name":"Data from Local System","tactic":"collection"},{"id":"T1027.003","name":"Steganography","tactic":"stealth"},{"id":"T1049","name":"System Network Connections Discovery","tactic":"discovery"},{"id":"T1057","name":"Process Discovery","tactic":"discovery"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1189","name":"Drive-by Compromise","tactic":"initial-access"},{"id":"T1203","name":"Exploitation for Client Execution","tactic":"execution"},{"id":"T1204.002","name":"Malicious File","tactic":"execution"},{"id":"T1566.001","name":"Spearphishing Attachment","tactic":"initial-access"},{"id":"T1588.001","name":"Malware","tactic":"resource-development"},{"id":"T1590.005","name":"IP Addresses","tactic":"reconnaissance"},{"id":"T1592.002","name":"Software","tactic":"reconnaissance"}]', '["Rifdoor","gh0st RAT"]', '[]', '2021-09-29', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
