INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G1012', 'curium', 'CURIUM', '["Crimson Sandstorm","Tortoise Shell","TA456","Yellow Liderc"]', 'G1012', 'https://attack.mitre.org/groups/G1012', 'Unattributed / Mixed', '["Media"]', '["Middle East"]', 'CURIUM is an Iranian threat group, first reported in September 2019 and active since at least July 2018, targeting IT service providers in the Middle East. CURIUM has since invested in building relationships with potential targets via social media over a period of months to establish trust and confidence before sending malware. Security researchers note CURIUM has demonstrated great patience and persistence by chatting with potential targets daily and sending benign files to help lower their security consciousness.', '[{"id":"T1005","name":"Data from Local System","tactic":"collection"},{"id":"T1041","name":"Exfiltration Over C2 Channel","tactic":"exfiltration"},{"id":"T1048.002","name":"Exfiltration Over Asymmetric Encrypted Non-C2 Protocol","tactic":"exfiltration"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1082","name":"System Information Discovery","tactic":"discovery"},{"id":"T1124","name":"System Time Discovery","tactic":"discovery"},{"id":"T1189","name":"Drive-by Compromise","tactic":"initial-access"},{"id":"T1204.002","name":"Malicious File","tactic":"execution"},{"id":"T1505.003","name":"Web Shell","tactic":"persistence"},{"id":"T1566.001","name":"Spearphishing Attachment","tactic":"initial-access"},{"id":"T1566.003","name":"Spearphishing via Service","tactic":"initial-access"},{"id":"T1583.001","name":"Domains","tactic":"resource-development"},{"id":"T1583.003","name":"Virtual Private Server","tactic":"resource-development"},{"id":"T1583.004","name":"Server","tactic":"resource-development"},{"id":"T1