INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G1015', 'scattered-spider', 'Scattered Spider', '["Roasted 0ktapus","UNC3944","Octo Tempest","Storm-0875"]', 'G1015', 'https://attack.mitre.org/groups/G1015', 'Financial / Ransomware', '["Defense","Telecom","Technology","Retail","Manufacturing"]', '[]', 'Scattered Spider is a native English-speaking cybercriminal group active since at least 2022. The group initially targeted customer relationship management (CRM) providers, business process outsourcing (BPO) firms, and telecommunications and technology companies before expanding in 2023 to gaming, hospitality, retail, managed service provider (MSP), manufacturing, and financial sectors. Scattered Spider relies heavily on social engineering, including impersonating IT and help-desk staff, to gain initial access, bypass multi-factor authentication (MFA), and compromise enterprise networks. The group has adapted its tooling to evade endpoint detection and response (EDR) defenses and used ransomware for financial gain. Scattered Spider had expanded into hybrid cloud and identity environments, using help-desk impersonation and MFA bypass to obtain administrator access in Okta, AWS, and Office 365.', '[{"id":"T1003.003","name":"NTDS","tactic":"credential-access"},{"id":"T1006","name":"Direct Volume Access","tactic":"stealth"},{"id":"T1016","name":"System Network Configuration Discovery","tactic":"discovery"},{"id":"T1018","name":"Remote System Discovery","tactic":"discovery"},{"id":"T1021.001","name":"Remote Desktop Protocol","tactic":"lateral-movement"},{"id":"T1021.004","name":"SSH","tactic":"lateral-movement"},{"id":"T1021.007","name":"Cloud Services","tactic":"lateral-movement"},{"id":"T1041","name":"Exfiltration Over C2 Channel","tactic":"exfiltration"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1059.004","name":"Unix Shell","tactic":"execution"},{"id":"T1068","name":"Exploitation for Privilege Escalation","tactic":"privilege-escalation"},{"id":"T1069","name":"Permission Groups Discovery","tactic":"discovery"},{"id":"T1069.002","name":"Domain Groups","tactic":"discovery"},{"id":"T1070.008","name":"Clear Mailbox Data","tactic":"stealth"},{"id":"T1074","name":"Data Staged","tactic":"collection"},{"id":"T1078","name":"Valid Accounts","tactic":"stealth"},{"id":"T1078.004","name":"Cloud Accounts","tactic":"stealth"},{"id":"T1082","name":"System Information Discovery","tactic":"discovery"},{"id":"T1083","name":"File and Directory Discovery","tactic":"discovery"},{"id":"T1087","name":"Account Discovery","tactic":"discovery"},{"id":"T1087.002","name":"Domain Account","tactic":"discovery"},{"id":"T1090","name":"Proxy","tactic":"command-and-control"},{"id":"T1098","name":"Account Manipulation","tactic":"persistence"},{"id":"T1098.003","name":"Additional Cloud Roles","tactic":"persistence"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1114","name":"Email Collection","tactic":"collection"},{"id":"T1114.003","name":"Email Forwarding Rule","tactic":"collection"},{"id":"T1133","name":"External Remote Services","tactic":"persistence"},{"id":"T1136","name":"Create Account","tactic":"persistence"},{"id":"T1204","name":"User Execution","tactic":"execution"},{"id":"T1213.003","name":"Code Repositories","tactic":"collection"},{"id":"T1213.005","name":"Messaging Applications","tactic":"collection"},{"id":"T1217","name":"Browser Information Discovery","tactic":"discovery"},{"id":"T1219.002","name":"Remote Desktop Software","tactic":"command-and-control"},{"id":"T1484.002","name":"Trust Modification","tactic":"defense-impairment"},{"id":"T1486","name":"Data Encrypted for Impact","tactic":"impact"},{"id":"T1490","name":"Inhibit System Recovery","tactic":"impact"},{"id":"T1530","name":"Data from Cloud Storage","tactic":"collection"},{"id":"T1538","name":"Cloud Service Dashboard","tactic":"discovery"},{"id":"T1539","name":"Steal Web Session Cookie","tactic":"credential-access"},{"id":"T1543.002","name":"Systemd Service","tactic":"persistence"},{"id":"T1552.001","name":"Credentials In Files","tactic":"credential-access"},{"id":"T1552.004","name":"Private Keys","tactic":"credential-access"},{"id":"T1553.002","name":"Code Signing","tactic":"defense-impairment"},{"id":"T1555.005","name":"Password Managers","tactic":"credential-access"},{"id":"T1556.006","name":"Multi-Factor Authentication","tactic":"defense-impairment"},{"id":"T1556.009","name":"Conditional Access Policies","tactic":"defense-impairment"},{"id":"T1564.008","name":"Email Hiding Rules","tactic":"stealth"},{"id":"T1567.002","name":"Exfiltration to Cloud Storage","tactic":"exfiltration"},{"id":"T1572","name":"Protocol Tunneling","tactic":"command-and-control"},{"id":"T1578.002","name":"Create Cloud Instance","tactic":"defense-impairment"},{"id":"T1580","name":"Cloud Infrastructure Discovery","tactic":"discovery"},{"id":"T1583.001","name":"Domains","tactic":"resource-development"},{"id":"T1585.001","name":"Social Media Accounts","tactic":"resource-development"},{"id":"T1588.001","name":"Malware","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1589","name":"Gather Victim Identity Information","tactic":"reconnaissance"},{"id":"T1598","name":"Phishing for Information","tactic":"reconnaissance"},{"id":"T1598.003","name":"Spearphishing Link","tactic":"reconnaissance"},{"id":"T1598.004","name":"Spearphishing Voice","tactic":"reconnaissance"},{"id":"T1621","name":"Multi-Factor Authentication Request Generation","tactic":"credential-access"},{"id":"T1657","name":"Financial Theft","tactic":"impact"},{"id":"T1684.001","name":"Impersonation","tactic":"stealth"},{"id":"T1685","name":"Disable or Modify Tools","tactic":"defense-impairment"}]', '["BlackCat","ConnectWise","LaZagne","Mimikatz","Raccoon Stealer","Rclone","Tor","WarzoneRAT","ngrok"]', '["CVE-2015-2291"]', '2023-07-05', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
