INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G1024', 'akira', 'Akira', '["PUNK SPIDER","Howling Scorpius","GOLD SAHARA"]', 'G1024', 'https://attack.mitre.org/groups/G1024', 'Financial / Ransomware', '[]', '[]', 'Akira is a ransomware variant and ransomware deployment entity active since at least March 2023. Akira uses compromised credentials to access single-factor external access mechanisms such as VPNs for initial access, then various publicly-available tools and techniques for lateral movement. Akira operations are associated with "double extortion" ransomware activity, where data is exfiltrated from victim environments prior to encryption, with threats to publish files if a ransom is not paid. Technical analysis of Akira ransomware indicates variants capable of targeting Windows or VMWare ESXi hypervisors and multiple overlaps with Conti ransomware.', '[{"id":"T1018","name":"Remote System Discovery","tactic":"discovery"},{"id":"T1021.001","name":"Remote Desktop Protocol","tactic":"lateral-movement"},{"id":"T1027.001","name":"Binary Padding","tactic":"stealth"},{"id":"T1036.005","name":"Match Legitimate Resource Name or Location","tactic":"stealth"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1078","name":"Valid Accounts","tactic":"stealth"},{"id":"T1133","name":"External Remote Services","tactic":"persistence"},{"id":"T1213.002","name":"Sharepoint","tactic":"collection"},{"id":"T1219","name":"Remote Access Tools","tactic":"command-and-control"},{"id":"T1482","name":"Domain Trust Discovery","tactic":"discovery"},{"id":"T1486","name":"Data Encrypted for Impact","tactic":"impact"},{"id":"T1531","name":"Account Access Removal","tactic":"impact"},{"id":"T1558","name":"Steal or Forge Kerberos Tickets","tactic":"credential-access"},{"id":"T1560.001","name":"Archive via Utility","tactic":"collection"},{"id":"T1567.002","name":"Exfiltration to Cloud Storage","tactic":"exfiltration"},{"id":"T1657","name":"Financial Theft","tactic":"impact"},{"id":"T1685","name":"Disable or Modify Tools","tactic":"defense-impairment"}]', '["AdFind","Akira","Akira _v2","LaZagne","Megazord","Mimikatz","PsExec","Rclone"]', '[]', '2024-02-20', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
--> statement-breakpoint
INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G0067', 'apt37', 'APT37', '["Ricochet Chollima","APT37","Reaper","Group123","TEMP.Reaper","ScarCruft","InkySquid"]', 'G0067', 'https://attack.mitre.org/groups/G0067', 'Espionage / State-Nexus', '[]', '["Middle East"]', 'APT37 is a North Korean state-sponsored cyber espionage group that has been active since at least 2012. The group has targeted victims primarily in South Korea, but also in Japan, Vietnam, Russia, Nepal, China, India, Romania, Kuwait, and other parts of the Middle East. APT37 has also been linked to the following campaigns between 2016-2018: Operation Daybreak, Operation Erebus, Golden Time, Evil New Year, Are you Happy?, FreeMilk, North Korean Human Rights, and Evil New Year 2018. North Korean group definitions are known to have significant overlap, and some security researchers report all North Korean state-sponsored cyber activity under the name Lazarus Group instead of tracking clusters or subgroups.', '[{"id":"T1005","name":"Data from Local System","tactic":"collection"},{"id":"T1027","name":"Obfuscated Files or Information","tactic":"stealth"},{"id":"T1027.003","name":"Steganography","tactic":"stealth"},{"id":"T1033","name":"System Owner/User Discovery","tactic":"discovery"},{"id":"T1036.001","name":"Invalid Code Signature","tactic":"stealth"},{"id":"T1053.005","name":"Scheduled Task","tactic":"execution"},{"id":"T1055","name":"Process Injection","tactic":"stealth"},{"id":"T1057","name":"Process Discovery","tactic":"discovery"},{"id":"T1059","name":"Command and Scripting Interpreter","tactic":"execution"},{"id":"T1059.003","name":"Windows Command Shell","tactic":"execution"},{"id":"T1059.005","name":"Visual Basic","tactic":"execution"},{"id":"T1059.006","name":"Python","tactic":"execution"},{"id":"T1071.001","name":"Web Protocols","tactic":"command-and-control"},{"id":"T1082","name":"System Information Discovery","tactic":"discovery"},{"id":"T1102.002","name":"Bidirectional Communication","tactic":"command-and-control"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1106","name":"Native API","tactic":"execution"},{"id":"T1120","name":"Peripheral Device Discovery","tactic":"discovery"},{"id":"T1123","name":"Audio Capture","tactic":"collection"},{"id":"T1189","name":"Drive-by Compromise","tactic":"initial-access"},{"id":"T1203","name":"Exploitation for Client Execution","tactic":"execution"},{"id":"T1204.002","name":"Malicious File","tactic":"execution"},{"id":"T1529","name":"System Shutdown/Reboot","tactic":"impact"},{"id":"T1547.001","name":"Registry Run Keys / Startup Folder","tactic":"persistence"},{"id":"T1548.002","name":"Bypass User Account Control","tactic":"privilege-escalation"},{"id":"T1555.003","name":"Credentials from Web Browsers","tactic":"credential-access"},{"id":"T1559.002","name":"Dynamic Data Exchange","tactic":"execution"},{"id":"T1561.002","name":"Disk Structure Wipe","tactic":"impact"},{"id":"T1566.001","name":"Spearphishing Attachment","tactic":"initial-access"}]', '["BLUELIGHT","CORALDECK","Cobalt Strike","DOGCALL","Final1stspy","HAPPYWORK","KARAE","NavRAT","POORAIM","ROKRAT","SHUTTERSPEED","SLOWDRIFT","WINERACK"]', '["CVE-2016-4117","CVE-2018-4878","CVE-2017-0199","CVE-2020-1380","CVE-2020-26411","CVE-2021-26411"]', '2018-04-18', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
