INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G1009', 'moses-staff', 'Moses Staff', '["DEV-0500","Marigold Sandstorm"]', 'G1009', 'https://attack.mitre.org/groups/G1009', 'Espionage / State-Nexus', '["Government","Finance","Energy","Manufacturing"]', '[]', 'Moses Staff is a suspected Iranian threat group that has primarily targeted Israeli companies since at least September 2021. Moses Staff openly stated their motivation in attacking Israeli companies is to cause damage by leaking stolen sensitive data and encrypting the victim''s networks without a ransom demand. Security researchers assess Moses Staff is politically motivated, and has targeted government, finance, travel, energy, manufacturing, and utility companies outside of Israel as well, including those in Italy, India, Germany, Chile, Turkey, the UAE, and the US.', '[{"id":"T1016","name":"System Network Configuration Discovery","tactic":"discovery"},{"id":"T1021.002","name":"SMB/Windows Admin Shares","tactic":"lateral-movement"},{"id":"T1027.013","name":"Encrypted/Encoded File","tactic":"stealth"},{"id":"T1082","name":"System Information Discovery","tactic":"discovery"},{"id":"T1087.001","name":"Local Account","tactic":"discovery"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1505.003","name":"Web Shell","tactic":"persistence"},{"id":"T1553.002","name":"Code Signing","tactic":"defense-impairment"},{"id":"T1587.001","name":"Malware","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1686.003","name":"Windows Host Firewall","tactic":"defense-impairment"}]', '["DCSrv","PsExec","PyDCrypt","StrifeWater"]', '[]', '2022-08-11', '2026-07-31', strftim