INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G0122', 'silent-librarian', 'Silent Librarian', '["TA407","COBALT DICKENS"]', 'G0122', 'https://attack.mitre.org/groups/G0122', 'Espionage / State-Nexus', '["Government"]', '[]', 'Silent Librarian is a group that has targeted research and proprietary data at universities, government agencies, and private sector companies worldwide since at least 2013. Members of Silent Librarian are known to have been affiliated with the Iran-based Mabna Institute which has conducted cyber intrusions at the behest of the government of Iran, specifically the Islamic Revolutionary Guard Corps (IRGC).', '[{"id":"T1078","name":"Valid Accounts","tactic":"stealth"},{"id":"T1110.003","name":"Password Spraying","tactic":"credential-access"},{"id":"T1114","name":"Email Collection","tactic":"collection"},{"id":"T1114.003","name":"Email Forwarding Rule","tactic":"collection"},{"id":"T1583.001","name":"Domains","tactic":"resource-development"},{"id":"T1585.002","name":"Email Accounts","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1588.004","name":"Digital Certificates","tactic":"resource-development"},{"id":"T1589.002","name":"Email Addresses","tactic":"reconnaissance"},{"id":"T1589.003","name":"Employee Names","tactic":"reconnaissance"},{"id":"T1594","name":"Search Victim-Owned Websites","tactic":"reconnaissance"},{"id":"T1598.003","name":"Spearphishing Link","tactic":"reconnaissance"},{"id":"T1608.005","name":"Link Target","tactic":"resource-development"}]', '[]', '[]', '2021-02-03', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
