INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G1051', 'medusa-group', 'Medusa Group', '[]', 'G1051', 'https://attack.mitre.org/groups/G1051', 'Financial / Ransomware', '[]', '[]', 'Medusa Group has been active since at least 2021 and was initially operated as a closed ransomware group before evolving into a Ransomware-as-a-Service (RaaS) operation. Some reporting indicates that certain attacks may still be conducted directly by the ransomware’s core developers. Public sources have also referred to the group as “Spearwing” or “Medusa Actors.” Medusa Group employs living-off-the-land techniques, frequently leveraging publicly available tools and common remote management software to conduct operations. The group engages in double extortion tactics, exfiltrating data prior to encryption and threatening to publish stolen information if ransom demands are not met. For initial access, Medusa Group has exploited publicly known vulnerabilities, conducted phishing campaigns, and used credentials or access purchased from Initial Access Brokers (IABs). The group is opportunistic and has targeted a wide range of sectors globally.', '[{"id":"T1003.001","name":"LSASS Memory","tactic":"credential-access"},{"id":"T1003.003","name":"NTDS","tactic":"credential-access"},{"id":"T1016","name":"System Network Configuration Discovery","tactic":"discovery"},{"id":"T1018","name":"Remote System Discovery","tactic":"discovery"},{"id":"T1021.001","name":"Remote Desktop Protocol","tactic":"lateral-movement"},{"id":"T1027.002","name":"Software Packing","tactic":"stealth"},{"id":"T1027.010","name":"Command Obfuscation","tactic":"stealth"},{"id":"T1033","name":"System Owner/User Discovery","tactic":"discovery"},{"id":"T1046","name":"Network Service Discovery","tactic":"discovery"},{"id":"T1047","name":"Windows Management Instrumentation","tactic":"execution"},{"id":"T1057","name":"Process Discovery","tactic":"discovery"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1059.003","name":"Windows Command Shell","tactic":"execution"},{"id":"T1069.002","name":"Domain Groups","tactic":"discovery"},{"id":"T1070.003","name":"Clear Command History","tactic":"stealth"},{"id":"T1070.004","name":"File Deletion","tactic":"stealth"},{"id":"T1071.001","name":"Web Protocols","tactic":"command-and-control"},{"id":"T1072","name":"Software Deployment Tools","tactic":"execution"},{"id":"T1078","name":"Valid Accounts","tactic":"stealth"},{"id":"T1082","name":"System Information Discovery","tactic":"discovery"},{"id":"T1083","name":"File and Directory Discovery","tactic":"discovery"},{"id":"T1087.001","name":"Local Account","tactic":"discovery"},{"id":"T1090.003","name":"Multi-hop Proxy","tactic":"command-and-control"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1106","name":"Native API","tactic":"execution"},{"id":"T1112","name":"Modify Registry","tactic":"defense-impairment"},{"id":"T1135","name":"Network Share Discovery","tactic":"discovery"},{"id":"T1136.002","name":"Domain Account","tactic":"persistence"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1218.014","name":"MMC","tactic":"stealth"},{"id":"T1219","name":"Remote Access Tools","tactic":"command-and-control"},{"id":"T1486","name":"Data Encrypted for Impact","tactic":"impact"},{"id":"T1489","name":"Service Stop","tactic":"impact"},{"id":"T1490","name":"Inhibit System Recovery","tactic":"impact"},{"id":"T1505.003","name":"Web Shell","tactic":"persistence"},{"id":"T1518.001","name":"Security Software Discovery","tactic":"discovery"},{"id":"T1529","name":"System Shutdown/Reboot","tactic":"impact"},{"id":"T1543.003","name":"Windows Service","tactic":"persistence"},{"id":"T1548.002","name":"Bypass User Account Control","tactic":"p