INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G0009', 'deep-panda', 'Deep Panda', '["Deep Panda","Shell Crew","WebMasters","KungFu Kittens","PinkPanther","Black Vine"]', 'G0009', 'https://attack.mitre.org/groups/G0009', 'Espionage / State-Nexus', '["Government","Defense","Healthcare","Telecom"]', '[]', 'Deep Panda is a suspected Chinese threat group known to target many industries, including government, defense, financial, and telecommunications. The intrusion into healthcare company Anthem has been attributed to Deep Panda. This group is also known as Shell Crew, WebMasters, KungFu Kittens, and PinkPanther. Deep Panda also appears to be known as Black Vine based on the attribution of both group names to the Anthem intrusion. Some analysts track Deep Panda and APT19 as the same group, but it is unclear from open source information if the groups are the same.', '[{"id":"T1018","name":"Remote System Discovery","tactic":"discovery"},{"id":"T1021.002","name":"SMB/Windows Admin Shares","tactic":"lateral-movement"},{"id":"T1027.005","name":"Indicator Removal from Tools","tactic":"stealth"},{"id":"T1047","name":"Windows Management Instrumentation","tactic":"execution"},{"id":"T1057","name":"Process Discovery","tactic":"discovery"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1218.010","name":"Regsvr32","tactic":"stealth"},{"id":"T1505.003","name":"Web Shell","tactic":"persistence"},{"id":"T1546.008","name":"Accessibility Features","tactic":"privilege-escalation"},{"id":"T1564.003","name":"Hidden Window","tactic":"stealth"}]', '["Derusbi","Mivast","Net","Ping","Sakula","StreamEx","Tasklist"]', '[]', '2017-05-31', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
