ion","tactic":"execution"},{"id":"T1053.005","name":"Scheduled Task","tactic":"execution"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1070.004","name":"File Deletion","tactic":"stealth"},{"id":"T1071.004","name":"DNS","tactic":"command-and-control"},{"id":"T1078.001","name":"Default Accounts","tactic":"stealth"},{"id":"T1090.003","name":"Multi-hop Proxy","tactic":"command-and-control"},{"id":"T1095","name":"Non-Application Layer Protocol","tactic":"command-and-control"},{"id":"T1110","name":"Brute Force","tactic":"credential-access"},{"id":"T1110.003","name":"Password Spraying","tactic":"credential-access"},{"id":"T1112","name":"Modify Registry","tactic":"defense-impairment"},{"id":"T1114","name":"Email Collection","tactic":"collection"},{"id":"T1119","name":"Automated Collection","tactic":"collection"},{"id":"T1125","name":"Video Capture","tactic":"collection"},{"id":"T1133","name":"External Remote Services","tactic":"persistence"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1195","name":"Supply Chain Compromise","tactic":"initial-access"},{"id":"T1203","name":"Exploitation for Client Execution","tactic":"execution"},{"id":"T1210","name":"Exploitation of Remote Services","tactic":"lateral-movement"},{"id":"T1491.002","name":"External Defacement","tactic":"impact"},{"id":"T1505.003","name":"Web Shell","tactic":"persistence"},{"id":"T1550.002","name":"Pass the Hash","tactic":"lateral-movement"},{"id":"T1552.001","name":"Credentials In Files","tactic":"credential-access"},{"id":"T1560","name":"Archive Collected Data","tactic":"collection"},{"id":"T1561.002","name":"Disk Structure Wipe","tactic":"impact"},{"id":"T1567.002","name":"Exfiltration to Cloud Storage","tactic":"exfiltration"},{"id":"T1570","name":"Lateral Tool Transfer","tactic":"lateral-movement"},{"id":"T1571","name":"Non-Standard Port","tactic":"command-and-control"},{"id":"T1572","name":"Protocol Tunneling","tactic":"command-and-cont