INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G1050', 'water-galura', 'Water Galura', '["GOLD FEATHER"]', 'G1050', 'https://attack.mitre.org/groups/G1050', 'Financial / Ransomware', '[]', '[]', 'Water Galura are the operators of the Qilin Ransomware-as-a-Service (RaaS) who handle payload generation, ransom negotiations, and the publication of stolen data for Qilin affilates recruited on Russian cybercrime forums. Water Galura have been active since at least 2022 and use a double extortion model where they demand payment for providing decryption keys and for refraining from publishing the stolen data to their leak site.', '[{"id":"T1486","name":"Data Encrypted for Impact","tactic":"impact"},{"id":"T1585.001","name":"Social Media Accounts","tactic":"resource-development"},{"id":"T1657","name":"Financial Theft","tactic":"impact"}]', '["Qilin","Tor"]', '[]', '2025-09-29', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
