INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G1026', 'malteiro', 'Malteiro', '[]', 'G1026', 'https://attack.mitre.org/groups/G1026', 'Financial / Ransomware', '[]', '["Europe","Latin America"]', 'Malteiro is a financially motivated criminal group that is likely based in Brazil and has been active since at least November 2019. The group operates and distributes the Mispadu banking trojan via a Malware-as-a-Service (MaaS) business model. Malteiro mainly targets victims throughout Latin America (particularly Mexico) and Europe (particularly Spain and Portugal).', '[{"id":"T1027.013","name":"Encrypted/Encoded File","tactic":"stealth"},{"id":"T1055.001","name":"Dynamic-link Library Injection","tactic":"stealth"},{"id":"T1059.005","name":"Visual Basic","tactic":"execution"},{"id":"T1082","name":"System Information Discovery","tactic":"discovery"},{"id":"T1140","name":"Deobfuscate/Decode Files or Information","tactic":"stealth"},{"id":"T1204.002","name":"Malicious File","tactic":"execution"},{"id":"T1518.001","name":"Security Software Discovery","tactic":"discovery"},{"id":"T1555","name":"Credentials from Password Stores","tactic":"credential-access"},{"id":"T1555.003","name":"Credentials from Web Browsers","tactic":"credential-access"},{"id":"T1566.001","name":"Spearphishing Attachment","tactic":"initial-access"},{"id":"T1614.001","name":"System Language Discovery","tactic":"discovery"},{"id":"T1657","name":"Financial Theft","tactic":"impact"}]', '["Mispadu"]', '[]', '2024-03-13', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
