INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G1013', 'metador', 'Metador', '[]', 'G1013', 'https://attack.mitre.org/groups/G1013', 'Espionage / State-Nexus', '["Telecom"]', '["Middle East","Africa"]', 'Metador is a suspected cyber espionage group that was first reported in September 2022. Metador has targeted a limited number of telecommunication companies, internet service providers, and universities in the Middle East and Africa. Security researchers named the group Metador based on the "I am meta" string in one of the group''s malware samples and the expectation of Spanish-language responses from C2 servers.', '[{"id":"T1027.013","name":"Encrypted/Encoded File","tactic":"stealth"},{"id":"T1059.003","name":"Windows Command Shell","tactic":"execution"},{"id":"T1070.004","name":"File Deletion","tactic":"stealth"},{"id":"T1071.001","name":"Web Protocols","tactic":"command-and-control"},{"id":"T1095","name":"Non-Application Layer Protocol","tactic":"command-and-control"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1546.003","name":"Windows Management Instrumentation Event Subscription","tactic":"privilege-escalation"},{"id":"T1588.001","name":"Malware","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"}]', '["Mafalda","metaMain"]', '[]', '2023-01-25', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
