INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G1044', 'apt42', 'APT42', '[]', 'G1044', 'https://attack.mitre.org/groups/G1044', 'Espionage / State-Nexus', '[]', '["Middle East"]', 'APT42 is an Iranian-sponsored threat group that conducts cyber espionage and surveillance. The group primarily focuses on targets in the Middle East region, but has targeted a variety of industries and countries since at least 2015. APT42 starts cyber operations through spearphishing emails and/or the PINEFLOWER Android malware, then monitors and collects information from the compromised systems and devices. Finally, APT42 exfiltrates data using native features and open-source tools. APT42 activities have been linked to Magic Hound by other commercial vendors. While there are behavior and software overlaps between Magic Hound and APT42, they appear to be distinct entities and are tracked as separate entities by their originating vendor.', '[{"id":"T1016","name":"System Network Configuration Discovery","tactic":"discovery"},{"id":"T1036.005","name":"Match Legitimate Resource Name or Location","tactic":"stealth"},{"id":"T1047","name":"Windows Management Instrumentation","tactic":"execution"},{"id":"T1053.005","name":"Scheduled Task","tactic":"execution"},{"id":"T1056","name":"Input Capture","tactic":"collection"},{"id":"T1056.001","name":"Keylogging","tactic":"collection"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1059.005","name":"Visual Basic","tactic":"execution"},{"id":"T1070","name":"Indicator Removal","tactic":"stealth"},{"id":"T1070.008","name":"Clear Mailbox Data","tactic":"stealth"},{"id":"T1071.001","name":"Web Protocols","tactic":"command-and-control"},{"id":"T1082","name":"System Information Discovery","tactic":"discovery"},{"id":"T1087.001","name":"Local Account","tactic":"discovery"},{"id":"T1102","name":"Web Service","tactic":"command-and-control"},{"id":"T1111","name":"Multi-Factor Authentication Interception","tactic":"credential-access"},{"id":"T1112","name":"Modify Registry","tactic":"defense-impairment"},{"id":"T1113","name":"Screen Capture","tactic":"collection"},{"id":"T1132.001","name":"Standard Encoding","tactic":"command-and-control"},{"id":"T1518.001","name":"Security Software Discovery","tactic":"discovery"},{"id":"T1530","name":"Data from Cloud Storage","tactic":"collection"},{"id":"T1539","name":"Steal Web Session Cookie","tactic":"credential-access"},{"id":"T1547","name":"Boot or Logon Autostart Execution","tactic":"persistence"},{"id":"T1555.003","name":"Credentials from Web Browsers","tactic":"credential-access"},{"id":"T1566.002","name":"Spearphishing Link","tactic":"initial-access"},{"id":"T1573.002","name":"Asymmetric Cryptography","tactic":"command-and-control"},{"id":"T1583.001","name":"Domains","tactic":"resource-development"},{"id":"T1583.003","name":"Virtual Private Server","tactic":"resource-development"},{"id":"T1585.002","name":"Email Accounts","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1608.001","name":"Upload Malware","tactic":"resource-development"},{"id":"T1682","name":"Query Public AI Services","tactic":"reconnaissance"},{"id":"T1684.001","name":"Impersonation","tactic":"stealth"}]', '["NICECURL","TAMECAT"]', '[]', '2025-01-08', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
