"collection"},{"id":"T1078.002","name":"Domain Accounts","tactic":"stealth"},{"id":"T1078.004","name":"Cloud Accounts","tactic":"stealth"},{"id":"T1083","name":"File and Directory Discovery","tactic":"discovery"},{"id":"T1098.007","name":"Additional Local or Domain Groups","tactic":"persistence"},{"id":"T1136.001","name":"Local Account","tactic":"persistence"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1505.003","name":"Web Shell","tactic":"persistence"},{"id":"T1554","name":"Compromise Host Software Binary","tactic":"persistence"},{"id":"T1560.001","name":"Archive via Utility","tactic":"collection"},{"id":"T1583.005","name":"Botnet","tactic":"resource-development"},{"id":"T1654","name":"Log Enumeration","tactic":"discovery"},{"id":"T1685","name":"Disable or Modify Tools","tactic":"defense-impairment"}]', '["Mimikatz","Net","PACEMAKER","PULSECHECK","PcShare","PoisonIvy","RAPIDPULSE","SLIGHTPULSE","SLOWPULSE","Skeleton Key","Tasklist","gh0st RAT","netstat"]', '[]', '2024-02-05', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
