INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G0044', 'winnti-group', 'Winnti Group', '["Winnti Group","Blackfly"]', 'G0044', 'https://attack.mitre.org/groups/G0044', 'Unattributed / Mixed', '[]', '[]', 'Winnti Group is a threat group with Chinese origins that has been active since at least 2010. The group has heavily targeted the gaming industry, but it has also expanded the scope of its targeting. Some reporting suggests a number of other groups, including Axiom, APT17, and Ke3chang, are closely linked to Winnti Group.', '[{"id":"T1014","name":"Rootkit","tactic":"stealth"},{"id":"T1057","name":"Process Discovery","tactic":"discovery"},{"id":"T1083","name":"File and Directory Discovery","tactic":"discovery"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1553.002","name":"Code Signing","tactic":"defense-impairment"},{"id":"T1583.001","name":"Domains","tactic":"resource-development"}]', '["PipeMon","PlugX","Winnti for Windows"]', '[]', '2017-05-31', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
