INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G0131', 'tonto-team', 'Tonto Team', '["CactusPete","Karma Panda","BRONZE HUNTLEY","Tonto Team","Earth Akhlut"]', 'G0131', 'https://attack.mitre.org/groups/G0131', 'Espionage / State-Nexus', '["Government","Healthcare","Energy","Technology","Education","Defense"]', '["United States","Europe","Eastern Europe"]', 'Tonto Team is a suspected Chinese state-sponsored cyber espionage threat group that has primarily targeted South Korea, Japan, Taiwan, and the United States since at least 2009, by 2020 they expanded operations to include other Asian as well as Eastern European countries. Tonto Team has targeted government, military, energy, mining, financial, education, healthcare, and technology organizations, including through the Heartbeat Campaign (2009-2012) and Operation Bitter Biscuit (2017).', '[{"id":"T1003","name":"OS Credential Dumping","tactic":"credential-access"},{"id":"T1056.001","name":"Keylogging","tactic":"collection"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1059.006","name":"Python","tactic":"execution"},{"id":"T1068","name":"Exploitation for Privilege Escalation","tactic":"privilege-escalation"},{"id":"T1069.001","name":"Local Groups","tactic":"discovery"},{"id":"T1090.002","name":"External Proxy","tactic":"command-and-control"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1135","name":"Network Share Discovery","tactic":"discovery"},{"id":"T1203","name":"Exploitation for Client Execution","tactic":"execution"},{"id":"T1204.002","name":"Malicious File","tactic":"execution"},{"id":"T1210","name":"Exploitation of Remote Services","tactic":"lateral-movement"},{"id":"T1505.003","name":"Web Shell","tactic":"persistence"},{"id":"T1566.001","name":"Spearphishing Attachment","tactic":"initial-access"},{"id":"T1574.001","name":"DLL","tactic":"stealth"}]', '["Bisonal","LaZagne","Mimikatz","NBTscan","ShadowPad","gsecdump"]', '["CVE-2018-0798","CVE-2018-8174","CVE-2018-0802","CVE-2017-11882","CVE-2019-9489","CVE-2020-8468","CVE-2019-0803"]', '2021-05-05', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
