INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G0115', 'gold-southfield', 'GOLD SOUTHFIELD', '["Pinchy Spider"]', 'G0115', 'https://attack.mitre.org/groups/G0115', 'Financial / Ransomware', '[]', '[]', 'GOLD SOUTHFIELD is a financially motivated threat group active since at least 2018 that operates the REvil Ransomware-as-a Service (RaaS). GOLD SOUTHFIELD provides backend infrastructure for affiliates recruited on underground forums to perpetrate high value deployments. By early 2020, GOLD SOUTHFIELD started capitalizing on the new trend of stealing data and further extorting the victim to pay for their data to not get publicly leaked.', '[{"id":"T1027.010","name":"Command Obfuscation","tactic":"stealth"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1113","name":"Screen Capture","tactic":"collection"},{"id":"T1133","name":"External Remote Services","tactic":"persistence"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1195.002","name":"Compromise Software Supply Chain","tactic":"initial-access"},{"id":"T1199","name":"Trusted Relationship","tactic":"initial-access"},{"id":"T1219","name":"Remote Access Tools","tactic":"command-and-control"},{"id":"T1566","name":"Phishing","tactic":"initial-access"}]', '["ConnectWise","REvil"]', '[]', '2020-09-22', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
--> statement-breakpoint
INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G0032', 'lazarus-group', 'Lazarus Group', '["Labyrinth Chollima","Diamond Sleet","ZINC","Lazarus Group","NICKEL ACADEMY","Guardians of Peace","HIDDEN COBRA"]', 'G0032', 'https://attack.mitre.org/groups/G0032', 'Unattributed / Mixed', '[]', '[]', 'Lazarus Group is a North Korean state-sponsored cyber threat group attributed to the Reconnaissance General Bureau (RGB). Lazarus Group has been active since at least 2009 and is reportedly responsible for the November 2014 destructive wiper attack on Sony Pictures Entertainment, identified by Novetta as part of Operation Blockbuster. Malware used by Lazarus Group correlates to other reported campaigns, including Operation Flame, Operation 1Mission, Operation Troy, DarkSeoul, and Ten Days of Rain. North Korea’s cyber operations have shown a consistent pattern of adaptation, forming and reorganizing units as national priorities shift. These units frequently share personnel, infrastructure, malware, and tradecraft, making it difficult to attribute specific operations with high confidence. Public reporting often uses “Lazarus Group” as an umbrella term for multiple North Korean cyber operators conducting espionage, destructive attacks, and financially motivated campaigns.', '[{"id":"T1001.003","name":"Protocol or Service Impersonation","tactic":"command-and-control"},{"id":"T1005","name":"Data from Local System","tactic":"collection"},{"id":"T1008","name":"Fallback Channels","tactic":"command-and-control"},{"id":"T1010","name":"Application Window Discovery","tactic":"discovery"},{"id":"T1012","name":"Query Registry","tactic":"discovery"},{"id":"T1016","name":"System Network Configuration Discovery","tactic":"discovery"},{"id":"T1021.001","name":"Remote Desktop Protocol","tactic":"lateral-move