INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G1006', 'earth-lusca', 'Earth Lusca', '["Charcoal Typhoon","ControlX","CHROMIUM","TAG-22"]', 'G1006', 'https://attack.mitre.org/groups/G1006', 'Unattributed / Mixed', '["Government","Telecom","Education","Media"]', '["United States"]', 'Earth Lusca is a suspected China-based cyber espionage group that has been active since at least April 2019. Earth Lusca has targeted organizations in Australia, China, Hong Kong, Mongolia, Nepal, the Philippines, Taiwan, Thailand, Vietnam, the United Arab Emirates, Nigeria, Germany, France, and the United States. Targets included government institutions, news media outlets, gambling companies, educational institutions, COVID-19 research organizations, telecommunications companies, religious movements banned in China, and cryptocurrency trading platforms, security researchers assess some Earth Lusca operations may be financially motivated. Earth Lusca has used malware commonly used by other Chinese threat groups, including APT41 and the Winnti Group cluster, however security researchers assess Earth Lusca''s techniques and infrastructure are separate.', '[{"id":"T1003.001","name":"LSASS Memory","tactic":"credential-access"},{"id":"T1003.006","name":"DCSync","tactic":"credential-access"},{"id":"T1007","name":"System Service Discovery","tactic":"discovery"},{"id":"T1016","name":"System Network Configuration Discovery","tactic":"discovery"},{"id":"T1018","name":"Remote System Discovery","tactic":"discovery"},{"id":"T1027","name":"Obfuscated Files or Information","tactic":"stealth"},{"id":"T1027.003","name":"Steganography","tactic":"stealth"},{"id":"T1033","name":"System Owner/User Discovery","tactic":"discovery"},{"id":"T1036.005","name":"Match Legitimate Resource Name or Location","tactic":"stealth"},{"id":"T1047","name":"Windows Management Instrumentation","tactic":"execution"},{"id":"T1049","name":"System Network Connections Discovery","tactic":"discovery"},{"id":"T1053.005","name":"Scheduled Task","tactic":"execution"},{"id":"T1057","name":"Process Discovery","tactic":"discovery"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1059.005","name":"Visual Basic","tactic":"execution"},{"id":"T1059.006","name":"Python","tactic":"execution"},{"id":"T1059.007","name":"JavaScript","tactic":"execution"},{"id":"T1090","name":"Proxy","tactic":"command-and-control"},{"id":"T1098.004","name":"SSH Authorized Keys","tactic":"persistence"},{"id":"T1112","name":"Modify Registry","tactic":"defense-impairment"},{"id":"T1140","name":"Deobfuscate/Decode Files or Information","tactic":"stealth"},{"id":"T1189","name":"Drive-by Compromise","tactic":"initial-access"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1204.001","name":"Malicious Link","tactic":"execution"},{"id":"T1204.002","name":"Malicious File","tactic":"execution"},{"id":"T1210","name":"Exploitation of Remote Services","tactic":"lateral-movement"},{"id":"T1218.005","name":"Mshta","tactic":"stealth"},{"id":"T1482","name":"Domain Trust Discovery","tactic":"discovery"},{"id":"T1543.003","name":"Windows Service","tactic":"persistence"},{"id":"T1547.012","name":"Print Processors","tactic":"persistence"},{"id":"T1548.002","name":"Bypass User Account Control","tactic":"privilege-escalation"},{"id":"T1560.001","name":"Archive via Utility","tactic":"collection"},{"id":"T1566.002","name":"Spearphishing Link","tactic":"initial-access"},{"id":"T1567.002","name":"Exfiltration to Cloud Storage","tactic":"exfiltration"},{"id":"T1574.001","name":"DLL","tactic":"stealth"},{"id":"T1583.001","name":"Domains","tactic":"resource-development"},{"id":"T1583.004","name":"Server","tactic":"resource-development"},{"id":"T1583.006","name":"Web Services","tactic":"resource-development"},{"id":"T1584.004","name":"Server","tactic":"resource-development"},{"id":"T1584.006","name":"Web Services","tactic":"resource-development"},{"id":"T1588.001","name":"Malware","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1595.002","name":"Vulnerability Scanning","tactic":"reconnaissance"},{"id":"T1608.001","name":"Upload Malware","tactic":"resource-development"}]', '["Cobalt Strike","Mimikatz","NBTscan","Nltest","PowerSploit","ShadowPad","Tasklist","Winnti for Linux","certutil"]', '["CVE-2020-1472"]', '2022-07-01', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
