"Data Manipulation","tactic":"impact"},{"id":"T1572","name":"Protocol Tunneling","tactic":"command-and-control"},{"id":"T1574.001","name":"DLL","tactic":"stealth"},{"id":"T1587.001","name":"Malware","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1589","name":"Gather Victim Identity Information","tactic":"reconnaissance"},{"id":"T1590.004","name":"Network Topology","tactic":"reconnaissance"},{"id":"T1657","name":"Financial Theft","tactic":"impact"}]', '["Empire","Impacket","Mimikatz","certutil"]', '["CVE-2017-1000486","CVE-2015-7450","CVE-2010-5326","CVE-2001-0507"]', '2023-07-27', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
