INSERT OR REPLACE INTO threat_actors (id, slug, name, aliases_json, mitre_id, mitre_url, motivation, target_sectors_json, target_regions_json, summary, techniques_json, software_json, cves_json, first_seen, last_seen, updated_at) VALUES ('G1057', 'shinyhunters', 'ShinyHunters', '["UNC6240","Bling Libra"]', 'G1057', 'https://attack.mitre.org/groups/G1057', 'Financial / Ransomware', '[]', '[]', 'ShinyHunters is a cyber criminal collective that has been active since at least 2019 operating under the ShinyCorp persona. ShinyHunters has targeted multiple industries and geographic regions gathering legitimate credentials and personally identifiable information (PII) for resale or extortion of victims. ShinyHunters has been associated with the broader collective called The Community, also known as The Com whose members have also included Scattered Spider and LAPSUS$. Public reporting has mentioned a variety of names for operations ShinyHunters members have reportedly conducted with members of other groups, including “Scattered Lapsus Hunters,” “Scattered Lapsus Shiny Hunters,” and “SLSH.”', '[{"id":"T1016","name":"System Network Configuration Discovery","tactic":"discovery"},{"id":"T1018","name":"Remote System Discovery","tactic":"discovery"},{"id":"T1036.005","name":"Match Legitimate Resource Name or Location","tactic":"stealth"},{"id":"T1059.007","name":"JavaScript","tactic":"execution"},{"id":"T1059.009","name":"Cloud API","tactic":"execution"},{"id":"T1069.003","name":"Cloud Groups","tactic":"discovery"},{"id":"T1072","name":"Software Deployment Tools","tactic":"execution"},{"id":"T1078","name":"Valid Accounts","tactic":"stealth"},{"id":"T1078.002","name":"Domain Accounts","tactic":"stealth"},{"id":"T1078.004","name":"Cloud Accounts","tactic":"stealth"},{"id":"T1082","name":"System Information Discovery","tactic":"discovery"},{"id":"T1083","name":"File and Directory Discovery","tactic":"discovery"},{"id":"T1090.003","name":"Multi-hop Proxy","tactic":"command-and-contro