econnaissance"},{"id":"T1595.002","name":"Vulnerability Scanning","tactic":"reconnaissance"},{"id":"T1598","name":"Phishing for Information","tactic":"reconnaissance"},{"id":"T1598.003","name":"Spearphishing Link","tactic":"reconnaissance"},{"id":"T1619","name":"Cloud Storage Object Discovery","tactic":"discovery"},{"id":"T1657","name":"Financial Theft","tactic":"impact"},{"id":"T1684","name":"Social Engineering","tactic":"stealth"}]', '["Tor"]', '["CVE-2026-35273"]', '2026-07-29', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
