INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0022', 'operation-dream-job', 'Operation Dream Job', 'C0022', 'https://attack.mitre.org/campaigns/C0022', 'Operation Dream Job was a cyber espionage operation likely conducted by Lazarus Group that targeted the defense, aerospace, government, and other sectors in the United States, Israel, Australia, Russia, and India. In at least one case, the cyber actors tried to monetize their network access to conduct a business email compromise (BEC) operation. In 2020, security researchers noted overlapping TTPs, to include fake job lures and code similarities, between Operation Dream Job, Operation North Star, and Operation Interception, by 2022 security researchers described Operation Dream Job as an umbrella term covering both Operation Interception and Operation North Star.', '["lazarus-group"]', '[{"id":"T1005","name":"Data from Local System","tactic":"collection"},{"id":"T1027.002","name":"Software Packing","tactic":"stealth"},{"id":"T1027.013","name":"Encrypted/Encoded File","tactic":"stealth"},{"id":"T1036.008","name":"Masquerade File Type","tactic":"stealth"},{"id":"T1041","name":"Exfiltration Over C2 Channel","tactic":"exfiltration"},{"id":"T1047","name":"Windows Management Instrumentation","tactic":"execution"},{"id":"T1053.005","name":"Scheduled Task","tactic":"execution"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1059.003","name":"Windows Command Shell","tactic":"execution"},{"id":"T1059.005","name":"Visual Basic","tactic":"execution"},{"id":"T1070.004","name":"File Deletion","tactic":"stealth"},{"id":"T1071.001","name":"Web Protocols","tactic":"command-and-control"},{"id":"T1083","name":"File and Directory Discovery","tactic":"discovery"},{"id":"T1087.002","name":"Domain Account","tactic":"discovery"},{"id