urce-development"},{"id":"T1587.002","name":"Code Signing Certificates","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1588.003","name":"Code Signing Certificates","tactic":"resource-development"},{"id":"T1589","name":"Gather Victim Identity Information","tactic":"reconnaissance"},{"id":"T1591","name":"Gather Victim Org Information","tactic":"reconnaissance"},{"id":"T1591.004","name":"Identify Roles","tactic":"reconnaissance"},{"id":"T1593.001","name":"Social Media","tactic":"reconnaissance"},{"id":"T1608.001","name":"Upload Malware","tactic":"resource-development"},{"id":"T1608.002","name":"Upload Tool","tactic":"resource-development"},{"id":"T1614.001","name":"System Language Discovery","tactic":"discovery"},{"id":"T1622","name":"Debugger Evasion","tactic":"stealth"},{"id":"T1684.001","name":"Impersonation","tactic":"stealth"}]', '["DRATzarus","Responder","Torisma"]', '[]', '["Government","Defense","Space"]', '["United States"]', '2023-03-17', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
