INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0035', 'kv-botnet-activity', 'KV Botnet Activity', 'C0035', 'https://attack.mitre.org/campaigns/C0035', 'KV Botnet Activity consisted of exploitation of primarily “end-of-life” small office-home office (SOHO) equipment from manufacturers such as Cisco, NETGEAR, and DrayTek. KV Botnet Activity was used by Volt Typhoon to obfuscate connectivity to victims in multiple critical infrastructure segments, including energy and telecommunication companies and entities based on the US territory of Guam. While the KV Botnet is the most prominent element of this campaign, it overlaps with another botnet cluster referred to as the JDY cluster. This botnet was disrupted by US law enforcement entities in early 2024 after periods of activity from October 2022 through January 2024.', '["volt-typhoon"]', '[{"id":"T1016","name":"System Network Configuration Discovery","tactic":"discovery"},{"id":"T1036","name":"Masquerading","tactic":"stealth"},{"id":"T1036.004","name":"Masquerade Task or Service","tactic":"stealth"},{"id":"T1055.009","name":"Proc Memory","tactic":"stealth"},{"id":"T1057","name":"Process Discovery","tactic":"discovery"},{"id":"T1059.004","name":"Unix Shell","tactic":"execution"},{"id":"T1070.004","name":"File Deletion","tactic":"stealth"},{"id":"T1082","name":"System Information Discovery","tactic":"discovery"},{"id":"T1083","name":"File and Directory Discovery","tactic":"discovery"},{"id":"T1095","name":"Non-Application Layer Protocol","tactic":"command-and-control"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1222.002","name":"Linux and Mac Permissions","tactic":"defense-impairment"},{"id":"T1518.001","name":"Security Software Discovery","tactic":"discovery"},{"id":"T1546","name":"Event Triggered Execution","tactic":"privilege-escalation"},{"id":"T1564.013","name":"Bind Mounts","tactic":"stealth"},{"id":"T1571","name":"Non-Standard Port","tactic":"command-and-control"},{"id":"T1573","name":"Encrypted Channel","tactic":"command-and-control"},{"id":"T1583.003","name":"Virtual Private Server","tactic":"resource-development"},{"id":"T1584.008","name":"Network Devices","tactic":"resource-development"},{"id":"T1685","name":"Disable or Modify Tools","tactic":"defense-impairment"}]', '[]', '[]', '["Energy","Telecom"]', '[]', '2024-06-10', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
