INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0058', 'sharepoint-toolshell-exploitation', 'SharePoint ToolShell Exploitation', 'C0058', 'https://attack.mitre.org/campaigns/C0058', 'The SharePoint ToolShell Exploitation campaign was conducted in July 2025 and encompassed the first waves of exploitation against incompletely patched spoofing (CVE-2025-49706) and remote code execution (CVE-2025-49704) vulnerabilities affecting on-premises Microsoft SharePoint servers. Later patched and updated as CVE-2025-53770 and CVE-2025-53771, the ToolShell vulnerabilities were widely exploited including by China-based ransomware actor Storm-2603 and espionage actors Threat Group-3390 and ZIRCONIUM. SharePoint ToolShell Exploitation targeted multiple regions and industries including finance, education, energy, and healthcare across Asia, Europe, and the United States.', '[]', '[{"id":"T1003.001","name":"LSASS Memory","tactic":"credential-access"},{"id":"T1005","name":"Data from Local System","tactic":"collection"},{"id":"T1027.002","name":"Software Packing","tactic":"stealth"},{"id":"T1027.010","name":"Command Obfuscation","tactic":"stealth"},{"id":"T1033","name":"System Owner/User Discovery","tactic":"discovery"},{"id":"T1041","name":"Exfiltration Over C2 Channel","tactic":"exfiltration"},{"id":"T1047","name":"Windows Management Instrumentation","tactic":"execution"},{"id":"T1053.005","name":"Scheduled Task","tactic":"execution"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1059.003","name":"Windows Command Shell","tactic":"execution"},{"id":"T1071.001","name":"Web Protocols","tactic":"command-and-control"},{"id":"T1074.001","name":"Local Data Staging","tactic":"collection"},{"id":"T1082","name":"System Information Discovery","tactic":"discovery"},{"id":"T1083","name":"File and Directory Discovery","tactic":"discovery"},{"id":"T1090","name":"Proxy","tactic":"command-and-control"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1112","name":"Modify Registry","tactic":"defense-impairment"},{"id":"T1119","name":"Automated Collection","tactic":"collection"},{"id":"T1140","name":"Deobfuscate/Decode Files or Information","tactic":"stealth"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1484.001","name":"Group Policy Modification","tactic":"defense-impairment"},{"id":"T1486","name":"Data Encrypted for Impact","tactic":"impact"},{"id":"T1505.003","name":"Web Shell","tactic":"persistence"},{"id":"T1505.004","name":"IIS Components","tactic":"persistence"},{"id":"T1552.001","name":"Credentials In Files","tactic":"credential-access"},{"id":"T1569.002","name":"Service Execution","tactic":"execution"},{"id":"T1570","name":"Lateral Tool Transfer","tactic":"lateral-movement"},{"id":"T1572","name":"Protocol Tunneling","tactic":"command-and-control"},{"id":"T1583.001","name":"Domains","tactic":"resource-development"},{"id":"T1585.002","name":"Email Accounts","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1595.002","name":"Vulnerability Scanning","tactic":"reconnaissance"},{"id":"T1620","name":"Reflective Code Loading","tactic":"stealth"},{"id":"T1657","name":"Financial Theft","tactic":"impact"},{"id":"T1685","name":"Disable or Modify Tools","tactic":"defense-impairment"}]', '["Impacket","Mimikatz","PsExec","ngrok"]', '["CVE-2025-49706","CVE-2025-49704","CVE-2025-53770","CVE-2025-53771"]', '["Finance","Healthcare","Energy","Education"]', '["United States","Europe"]', '2025-10-15', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
