cate/Decode Files or Information","tactic":"stealth"},{"id":"T1203","name":"Exploitation for Client Execution","tactic":"execution"},{"id":"T1204.002","name":"Malicious File","tactic":"execution"},{"id":"T1221","name":"Template Injection","tactic":"stealth"},{"id":"T1497.001","name":"System Checks","tactic":"stealth"},{"id":"T1518.001","name":"Security Software Discovery","tactic":"discovery"},{"id":"T1566.001","name":"Spearphishing Attachment","tactic":"initial-access"},{"id":"T1573.001","name":"Symmetric Cryptography","tactic":"command-and-control"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"}]', '["Empire"]', '["CVE-2017-11882"]', '[]', '[]', '2022-09-07', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
