"id":"T1566.002","name":"Spearphishing Link","tactic":"initial-access"},{"id":"T1574.001","name":"DLL","tactic":"stealth"},{"id":"T1583.001","name":"Domains","tactic":"resource-development"},{"id":"T1588.004","name":"Digital Certificates","tactic":"resource-development"},{"id":"T1608.001","name":"Upload Malware","tactic":"resource-development"}]', '["PlugX","ShadowPad"]', '[]', '[]', '["Southeast Asia"]', '2025-01-14', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
