on","tactic":"stealth"},{"id":"T1203","name":"Exploitation for Client Execution","tactic":"execution"},{"id":"T1205","name":"Traffic Signaling","tactic":"stealth"},{"id":"T1554","name":"Compromise Host Software Binary","tactic":"persistence"},{"id":"T1571","name":"Non-Standard Port","tactic":"command-and-control"},{"id":"T1573.001","name":"Symmetric Cryptography","tactic":"command-and-control"},{"id":"T1587.001","name":"Malware","tactic":"resource-development"},{"id":"T1690","name":"Prevent Command History Logging","tactic":"defense-impairment"}]', '["MEDUSA","REPTILE"]', '["CVE-2025-21590"]', '[]', '[]', '2025-06-24', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
