INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0006', 'operation-honeybee', 'Operation Honeybee', 'C0006', 'https://attack.mitre.org/campaigns/C0006', 'Operation Honeybee was a campaign that targeted humanitarian aid and inter-Korean affairs organizations from at least late 2017 through early 2018. Operation Honeybee initially targeted South Korea, but expanded to include Vietnam, Singapore, Japan, Indonesia, Argentina, and Canada. Security researchers assessed the threat actors were likely Korean speakers based on metadata used in both lure documents and executables, and named the campaign "Honeybee" after the author name discovered in malicious Word documents.', '[]', '[{"id":"T1005","name":"Data from Local System","tactic":"collection"},{"id":"T1027.013","name":"Encrypted/Encoded File","tactic":"stealth"},{"id":"T1036","name":"Masquerading","tactic":"stealth"},{"id":"T1036.005","name":"Match Legitimate Resource Name or Location","tactic":"stealth"},{"id":"T1041","name":"Exfiltration Over C2 Channel","tactic":"exfiltration"},{"id":"T1057","name":"Process Discovery","tactic":"discovery"},{"id":"T1059.003","name":"Windows Command Shell","tactic":"execution"},{"id":"T1059.005","name":"Visual Basic","tactic":"execution"},{"id":"T1070.004","name":"File Deletion","tactic":"stealth"},{"id":"T1071.002","name":"File Transfer Protocols","tactic":"command-and-control"},{"id":"T1074.001","name":"Local Data Staging","tactic":"collection"},{"id":"T1082","name":"System Information Discovery","tactic":"discovery"},{"id":"T1083","name":"File and Directory Discovery","tactic":"discovery"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1106","name":"Native API","tactic":"execution"},{"id":"T1112","name":"Modify Registry","tactic":"defense-impairment"},{"id":"T1140","name":"Deobfuscate/Decode Files or Information","tactic":"stealth"},{"id":"T1204.002","name":"Malicious File","tactic":"execution"},{"id":"T1543.003","name":"Windows Service","tactic":"persistence"},{"id":"T1548.002","name":"Bypass User Account Control","tactic":"privilege-escalation"},{"id":"T1553.002","name":"Code Signing","tactic":"defense-impairment"},{"id":"T1560.001","name":"Archive via Utility","tactic":"collection"},{"id":"T1569.002","name":"Service Execution","tactic":"execution"},{"id":"T1574.011","name":"Services Registry Permissions Weakness","tactic":"stealth"},{"id":"T1583.001","name":"Domains","tactic":"resource-development"},{"id":"T1583.004","name":"Server","tactic":"resource-development"},{"id":"T1585.002","name":"Email Accounts","tactic":"resource-development"},{"id":"T1588.004","name":"Digital Certificates","tactic":"resource-development"}]', '["Reg","SYSCON","Systeminfo","Tasklist","cmd"]', '[]', '[]', '[]', '2022-09-16', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
