INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0030', 'triton-safety-instrumented-system-attack', 'Triton Safety Instrumented System Attack', 'C0030', 'https://attack.mitre.org/campaigns/C0030', 'Triton Safety Instrumented System Attack was a campaign employed by TEMP.Veles which leveraged the Triton malware framework against a petrochemical organization. The malware and techniques used within this campaign targeted specific Triconex Safety Controllers within the environment. The incident was eventually discovered due to a safety trip that occurred as a result of an issue in the malware.', '["temp-veles"]', '[{"id":"T1003.001","name":"LSASS Memory","tactic":"credential-access"},{"id":"T1027.005","name":"Indicator Removal from Tools","tactic":"stealth"},{"id":"T1036.005","name":"Match Legitimate Resource Name or Location","tactic":"stealth"},{"id":"T1053.005","name":"Scheduled Task","tactic":"execution"},{"id":"T1056.003","name":"Web Portal Capture","tactic":"collection"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1573","name":"Encrypted Channel","tactic":"command-and-control"},{"id":"T1587.001","name":"Malware","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1595","name":"Active Scanning","tactic":"reconnaissance"}]', '["Mimikatz"]', '[]', '[]', '[]', '2024-03-25', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
