INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0016', 'operation-dust-storm', 'Operation Dust Storm', 'C0016', 'https://attack.mitre.org/campaigns/C0016', 'Operation Dust Storm was a long-standing persistent cyber espionage campaign that targeted multiple industries in Japan, South Korea, the United States, Europe, and several Southeast Asian countries. By 2015, the Operation Dust Storm threat actors shifted from government and defense-related intelligence targets to Japanese companies or Japanese subdivisions of larger foreign organizations supporting Japan''s critical infrastructure, including electricity generation, oil and natural gas, finance, transportation, and construction. Operation Dust Storm threat actors also began to use Android backdoors in their operations by 2015, with all identified victims at the time residing in Japan or South Korea.', '[]', '[{"id":"T1027.002","name":"Software Packing","tactic":"stealth"},{"id":"T1027.013","name":"Encrypted/Encoded File","tactic":"stealth"},{"id":"T1036","name":"Masquerading","tactic":"stealth"},{"id":"T1059.005","name":"Visual Basic","tactic":"execution"},{"id":"T1059.007","name":"JavaScript","tactic":"execution"},{"id":"T1140","name":"Deobfuscate/Decode Files or Information","tactic":"stealth"},{"id":"T1189","name":"Drive-by Compromise","tactic":"initial-access"},{"id":"T1203","name":"Exploitation for Client Execution","tactic":"execution"},{"id":"T1204.001","name":"Malicious Link","tactic":"execution"},{"id":"T1204.002","name":"Malicious File","tactic":"execution"},{"id":"T1218.005","name":"Mshta","tactic":"stealth"},{"id":"T1518","name":"Software Discovery","tactic":"discovery"},{"id":"T1566.001","name":"Spearphishing Attachment","tactic":"initial-access"},{"id":"T1566.002","name":"Spearphishing Link","tactic":"initial-access"},{"id":"T1568","name":"Dynamic Resolution","tactic":"command-and-control"},{"id":"T1583.001","name":"Domains","tactic":"resource-development"},{"id":"T1585.002","name":"Email Accounts","tactic":"resource-development"}]', '["Mis-Type","Misdat","PoisonIvy","S-Type","ZLib","gh0st RAT"]', '["CVE-2014-0322","CVE-2011-0611","CVE-2010-1885","CVE-2011-1255","CVE-2012-1889"]', '["Government","Defense","Finance","Transportation"]', '["United States","Europe","Southeast Asia"]', '2022-09-29', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
