INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0028', '2015-ukraine-electric-power-attack', '2015 Ukraine Electric Power Attack', 'C0028', 'https://attack.mitre.org/campaigns/C0028', '2015 Ukraine Electric Power Attack was a Sandworm Team campaign during which they used BlackEnergy (specifically BlackEnergy3) and KillDisk to target and disrupt transmission and distribution substations within the Ukrainian power grid. This campaign was the first major public attack conducted against the Ukrainian power grid by Sandworm Team.', '["sandworm-team"]', '[{"id":"T1018","name":"Remote System Discovery","tactic":"discovery"},{"id":"T1040","name":"Network Sniffing","tactic":"credential-access"},{"id":"T1055","name":"Process Injection","tactic":"stealth"},{"id":"T1056.001","name":"Keylogging","tactic":"collection"},{"id":"T1059.005","name":"Visual Basic","tactic":"execution"},{"id":"T1070.004","name":"File Deletion","tactic":"stealth"},{"id":"T1071.001","name":"Web Protocols","tactic":"command-and-control"},{"id":"T1078","name":"Valid Accounts","tactic":"stealth"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1112","name":"Modify Registry","tactic":"defense-impairment"},{"id":"T1133","name":"External Remote Services","tactic":"persistence"},{"id":"T1136.002","name":"Domain Account","tactic":"persistence"},{"id":"T1204.002","name":"Malicious File","tactic":"execution"},{"id":"T1218.011","name":"Rundll32","tactic":"stealth"},{"id":"T1566.001","name":"Spearphishing Attachment","tactic":"initial-access"},{"id":"T1570","name":"Lateral Tool Transfer","tactic":"lateral-movement"},{"id":"T1685","name":"Disable or Modify Tools","tactic":"defense-impairment"}]', '["BlackEnergy","KillDisk"]', '[]', '["Energy"]', '[]', '2023-09-27', '2026-08-04', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
