INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0043', 'indian-critical-infrastructure-intrusions', 'Indian Critical Infrastructure Intrusions', 'C0043', 'https://attack.mitre.org/campaigns/C0043', 'Indian Critical Infrastructure Intrusions is a sequence of intrusions from 2021 through early 2022 linked to People’s Republic of China (PRC) threat actors, particularly RedEcho and Threat Activity Group 38 (TAG38). The intrusions appear focused on IT system breach in Indian electric utility entities and logistics firms, as well as potentially managed service providers operating within India. Although focused on OT-operating entities, there is no evidence this campaign was able to progress beyond IT breach and information gathering to OT environment access.', '[]', '[{"id":"T1071.001","name":"Web Protocols","tactic":"command-and-control"},{"id":"T1568","name":"Dynamic Resolution","tactic":"command-and-control"},{"id":"T1571","name":"Non-Standard Port","tactic":"command-and-control"},{"id":"T1573.002","name":"Asymmetric Cryptography","tactic":"command-and-control"},{"id":"T1583.001","name":"Domains","tactic":"resource-development"},{"id":"T1584","name":"Compromise Infrastructure","tactic":"resource-development"},{"id":"T1588.004","name":"Digital Certificates","tactic":"resource-development"},{"id":"T1599","name":"Network Boundary Bridging","tactic":"defense-impairment"}]', '["FRP","ShadowPad"]', '[]', '[]', '[]', '2024-11-21', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
