INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0005', 'operation-spalax', 'Operation Spalax', 'C0005', 'https://attack.mitre.org/campaigns/C0005', 'Operation Spalax was a campaign that primarily targeted Colombian government organizations and private companies, particularly those associated with the energy and metallurgical industries. The Operation Spalax threat actors distributed commodity malware and tools using generic phishing topics related to COVID-19, banking, and law enforcement action. Security researchers noted indicators of compromise and some infrastructure overlaps with other campaigns dating back to April 2018, including at least one separately attributed to APT-C-36, however identified enough differences to report this as separate, unattributed activity.', '[]', '[{"id":"T1027.002","name":"Software Packing","tactic":"stealth"},{"id":"T1027.003","name":"Steganography","tactic":"stealth"},{"id":"T1027.013","name":"Encrypted/Encoded File","tactic":"stealth"},{"id":"T1059","name":"Command and Scripting Interpreter","tactic":"execution"},{"id":"T1102","name":"Web Service","tactic":"command-and-control"},{"id":"T1140","name":"Deobfuscate/Decode Files or Information","tactic":"stealth"},{"id":"T1204.001","name":"Malicious Link","tactic":"execution"},{"id":"T1204.002","name":"Malicious File","tactic":"execution"},{"id":"T1218.011","name":"Rundll32","tactic":"stealth"},{"id":"T1497","name":"Virtualization/Sandbox Evasion","tactic":"stealth"},{"id":"T1566.001","name":"Spearphishing Attachment","tactic":"initial-access"},{"id":"T1566.002","name":"Spearphishing Link","tactic":"initial-access"},{"id":"T1568","name":"Dynamic Resolution","tactic":"command-and-control"},{"id":"T1583.001","name":"Domains","tactic":"resource-development"},{"id":"T1588.001","name":"Malware","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1608.001","name":"Upload Malware","tactic":"resource-development"}]', '["Remcos","njRAT"]', '[]', '["Government","Energy"]', '[]', '2022-09-16', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
