INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0057', '3cx-supply-chain-attack', '3CX Supply Chain Attack', 'C0057', 'https://attack.mitre.org/campaigns/C0057', 'The 3CX Supply Chain Attack was the first publicly reported case of one supply chain compromise triggering another, leading to a cascading, two-stage intrusion. The initial supply chain attack began when a 3CX employee downloaded and executed a trojanized, end-of-life version of the X_Trader trading software from Trading Technologies. This provided UNC4736, a threat cluster associated with AppleJeus, access to the 3CX environment. From there UNC4736 compromised the Windows and macOS build environments used to distribute the 3CX desktop application to their customers. While 3CX serves more than 600,000 customers and 12 million users, only a subset of systems were affected. Subsequent targeting focused on victims in the defense and cryptocurrency sectors, where attackers deployed secondary payloads such as Gopuram for credential theft and persistence. The campaign began in late 2022 and was disrupted after security vendors publicly reported the compromise in March 2023.', '["applejeus"]', '[{"id":"T1027","name":"Obfuscated Files or Information","tactic":"stealth"},{"id":"T1027.009","name":"Embedded Payloads","tactic":"stealth"},{"id":"T1027.013","name":"Encrypted/Encoded File","tactic":"stealth"},{"id":"T1055","name":"Process Injection","tactic":"stealth"},{"id":"T1055.002","name":"Portable Executable Injection","tactic":"stealth"},{"id":"T1071.001","name":"Web Protocols","tactic":"command-and-control"},{"id":"T1078","name":"Valid Accounts","tactic":"stealth"},{"id":"T1102.001","name":"Dead Drop Resolver","tactic":"command-and-control"},{"id":"T1189","name":"Drive-by Compromise","tactic":"initial-access"},{"id":"T1195.002","name":"Compromise Software Supply Chain","tactic":"initial-access"},{"id":"T1203","name":"Exploitation for Client Execution","tactic":"execution"},{"id":"T1217","name":"Browser Information Discovery","tactic":"discovery"},{"id":"T1218.007","name":"Msiexec","tactic":"stealth"},{"id":"T1218.015","name":"Electron Applications","tactic":"stealth"},{"id":"T1543.004","name":"Launch Daemon","tactic":"persistence"},{"id":"T1546.016","name":"Installer Packages","tactic":"privilege-escalation"},{"id":"T1553.002","name":"Code Signing","tactic":"defense-impairment"},{"id":"T1559","name":"Inter-Process Communication","tactic":"execution"},{"id":"T1573.001","name":"Symmetric Cryptography","tactic":"command-and-control"},{"id":"T1574.001","name":"DLL","tactic":"stealth"},{"id":"T1620","name":"Reflective Code Loading","tactic":"stealth"},{"id":"T1678","name":"Delay Execution","tactic":"stealth"}]', '["FRP"]', '["CVE-2022-0609"]', '["Defense"]', '[]', '2025-08-25', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
