INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0029', 'cutting-edge', 'Cutting Edge', 'C0029', 'https://attack.mitre.org/campaigns/C0029', 'Cutting Edge was a campaign conducted by suspected China-nexus espionage actors, variously identified as UNC5221/UTA0178 and UNC5325, that began as early as December 2023 with the exploitation of zero-day vulnerabilities in Ivanti Connect Secure (previously Pulse Secure) VPN appliances. Cutting Edge targeted the U.S. defense industrial base and multiple sectors globally including telecommunications, financial, aerospace, and technology. Cutting Edge featured the use of defense evasion and living-off-the-land (LoTL) techniques along with the deployment of web shells and other custom malware.', '[]', '[{"id":"T1003.001","name":"LSASS Memory","tactic":"credential-access"},{"id":"T1003.003","name":"NTDS","tactic":"credential-access"},{"id":"T1005","name":"Data from Local System","tactic":"collection"},{"id":"T1021.001","name":"Remote Desktop Protocol","tactic":"lateral-movement"},{"id":"T1021.002","name":"SMB/Windows Admin Shares","tactic":"lateral-movement"},{"id":"T1021.004","name":"SSH","tactic":"lateral-movement"},{"id":"T1027.013","name":"Encrypted/Encoded File","tactic":"stealth"},{"id":"T1055","name":"Process Injection","tactic":"stealth"},{"id":"T1056.001","name":"Keylogging","tactic":"collection"},{"id":"T1056.003","name":"Web Portal Capture","tactic":"collection"},{"id":"T1059","name":"Command and Scripting Interpreter","tactic":"execution"},{"id":"T1059.006","name":"Python","tactic":"execution"},{"id":"T1070","name":"Indicator Removal","tactic":"stealth"},{"id":"T1070.004","name":"File Deletion","tactic":"stealth"},{"id":"T1070.006","name":"Timestomp","tactic":"stealth"},{"id":"T1071.004","name":"DNS","tactic":"command-and-control"},{"id":"T1078.002","name":"Domain Accounts","tactic":"stealth"},{"id":"T1082","name":"System Information Discovery","tactic":"discovery"},{"id":"T1095","name":"Non-Application Layer Protocol","tactic":"command-and-control"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1205","name":"Traffic Signaling","tactic":"stealth"},{"id":"T1505.003","name":"Web Shell","tactic":"persistence"},{"id":"T1554","name":"Compromise Host Software Binary","tactic":"persistence"},{"id":"T1560.001","name":"Archive via Utility","tactic":"collection"},{"id":"T1572","name":"Protocol Tunneling","tactic":"command-and-control"},{"id":"T1584.008","name":"Network Devices","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1594","name":"Search Victim-Owned Websites","tactic":"reconnaissance"},{"id":"T1595.002","name":"Vulnerability Scanning","tactic":"reconnaissance"},{"id":"T1685","name":"Disable or Modify Tools","tactic":"defense-impairment"}]', '["BUSHWALK","CrackMapExec","FRAMESTING","GLASSTOKEN","Impacket","LIGHTWIRE","LITTLELAMB.WOOLTEA","PITSTOP","WARPWIRE","WIREFIRE","ZIPLINE"]', '["CVE-2024-21893","CVE-2023-46805","CVE-2024-21887"]', '["Defense","Telecom","Technology","Space"]', '[]', '2024-03-01', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
