INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0018', 'c0018', 'C0018', 'C0018', 'https://attack.mitre.org/campaigns/C0018', 'C0018 was a month-long ransomware intrusion that successfully deployed AvosLocker onto a compromised network. The unidentified actors gained initial access to the victim network through an exposed server and used a variety of open-source tools prior to executing AvosLocker.', '[]', '[{"id":"T1016","name":"System Network Configuration Discovery","tactic":"discovery"},{"id":"T1021.001","name":"Remote Desktop Protocol","tactic":"lateral-movement"},{"id":"T1027.010","name":"Command Obfuscation","tactic":"stealth"},{"id":"T1033","name":"System Owner/User Discovery","tactic":"discovery"},{"id":"T1036","name":"Masquerading","tactic":"stealth"},{"id":"T1036.005","name":"Match Legitimate Resource Name or Location","tactic":"stealth"},{"id":"T1046","name":"Network Service Discovery","tactic":"discovery"},{"id":"T1047","name":"Windows Management Instrumentation","tactic":"execution"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1071.001","name":"Web Protocols","tactic":"command-and-control"},{"id":"T1072","name":"Software Deployment Tools","tactic":"execution"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1218.011","name":"Rundll32","tactic":"stealth"},{"id":"T1219.002","name":"Remote Desktop Software","tactic":"command-and-control"},{"id":"T1486","name":"Data Encrypted for Impact","tactic":"impact"},{"id":"T1570","name":"Lateral Tool Transfer","tactic":"lateral-movement"},{"id":"T1571","name":"Non-Standard Port","tactic":"command-and-control"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"}]', '["AvosLocker","Cobalt Strike","Mimikatz","Ping","Sliver","netsh"]', '["CVE-2021-44228","CVE-2021-45046","CVE-2021-45105","CVE-2021-44832"]', '[]', '[]', '2023-01-17', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
