INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0037', 'water-curupira-pikabot-distribution', 'Water Curupira Pikabot Distribution', 'C0037', 'https://attack.mitre.org/campaigns/C0037', 'Pikabot was distributed in Water Curupira Pikabot Distribution throughout 2023 by an entity linked to BlackBasta ransomware deployment via email attachments. This activity followed the take-down of QakBot, with several technical overlaps and similarities with QakBot, indicating a possible connection. The identified activity led to the deployment of tools such as Cobalt Strike, while coinciding with campaigns delivering DarkGate and IcedID en route to ransomware deployment.', '[]', '[{"id":"T1059.003","name":"Windows Command Shell","tactic":"execution"},{"id":"T1059.007","name":"JavaScript","tactic":"execution"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1140","name":"Deobfuscate/Decode Files or Information","tactic":"stealth"},{"id":"T1204","name":"User Execution","tactic":"execution"},{"id":"T1204.001","name":"Malicious Link","tactic":"execution"},{"id":"T1204.002","name":"Malicious File","tactic":"execution"},{"id":"T1218.011","name":"Rundll32","tactic":"stealth"},{"id":"T1566.001","name":"Spearphishing Attachment","tactic":"initial-access"},{"id":"T1589.002","name":"Email Addresses","tactic":"reconnaissance"}]', '["DarkGate","IcedID","Pikabot"]', '[]', '[]', '[]', '2024-07-17', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
--> statement-breakpoint
INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0045', 'shadowray', 'ShadowRay', 'C0045', 'https://attack.mitre.org/campaigns/C0045', 'ShadowRay was a campaign that began in late 2023 targeting the education, cryptocurrency, biopharma, and other sectors through a vulnerability (CVE-2023-48022) in the Ray AI framework named ShadowRay. According to security researchers ShadowRay was the first known instance of AI workloads being activley exploited in the wild through vulnerabilities in AI infrastructure. CVE-2023-48022, which allows access to compute resources and sensitive data for exposed instances, remains unpatched and has been disputed by the vendor as they maintain that Ray is not intended for use outside of a strictly controlled network environment.', '[]', '[{"id":"T1003.008","name":"/etc/passwd and /etc/shadow","tactic":"credential-access"},{"id":"T1016","name":"System Network Configuration Discovery","tactic":"discovery"},{"id":"T1027.013","name":"Encrypted/Encoded File","tactic":"stealth"},{"id":"T1059.006","name":"Python","tactic":"execution"},{"id":"T1068","name":"Exploitation for Privilege Escalation","tactic":"privilege-escalation"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1496.001","name":"Compute Hijacking","tactic":"impact"},{"id":"T1546.004","name":"Unix Shell Configuration Modification","tactic":"privilege-escalation"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"}]', '[]', '["CVE-2023-48022"]', '["Education"]', '[]', '2024-12-02', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
--> statement-breakpoint
INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0050', 'j-magic-campaign', 'J-magic Campaign', 'C0050', 'https://attack.mitre.org/campaigns/C0050', 'The J-magic Campaign was active from mid-2023 to at least mid-2024 and featured the use of the J-magic backdoor, a custom cd00r variant tailored for use against Juniper routers. The J-magic Campaign targeted Junos OS routers serving as VPN gateways primarily in the semiconductor, energy, manufacturing, and IT sectors.', '[]', '[{"id":"T1036.005","name":"Match Legitimate Resource Name or Location","tactic":"stealth"},{"id":"T1583.003","name":"Virtual Private Server","tactic":"resource-development"},{"id":"T1587.003","name":"Digital Certificates","tactic":"resource-development"},{"id":"T1588.001","name":"Malware","tactic":"resource-development"}]', '["J-magic"]', '[]', '["Energy","Manufacturing"]', '[]', '2025-02-18', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
--> statement-breakpoint
INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0062', 'anthropic-ai-orchestrated-campaign', 'Anthropic AI-orchestrated Campaign', 'C0062', 'https://attack.mitre.org/campaigns/C0062', 'The Anthropic AI-orchestrated Campaign was conducted in September 2025 by a likely China nexus espionage actor identified as GTG-1002. The Anthropic AI-orchestrated Campaign was a highly coordinated operation that manipulated Claude Code to perform reconnaissance, vulnerability discovery, exploitation, lateral movement, credential harvesting, data analysis, and exfiltration operations at approximately 30 entities in the technology, financial, chemical, and government sectors. During the Anthropic AI-orchestrated Campaign, human operators used Claude Code agents and Model Context Protocol (MCP) tools to automate cyber operations. Operators broke attacks into discrete tasks, used crafted prompts, and established personas to bypass AI guardrails, enabling the agents to execute the operations with minimal human involvement.', '[]', '[{"id":"T1005","name":"Data from Local System","tactic":"collection"},{"id":"T1016","name":"System Network Configuration Discovery","tactic":"discovery"},{"id":"T1046","name":"Network Service Discovery","tactic":"discovery"},{"id":"T1049","name":"System Network Connections Discovery","tactic":"discovery"},{"id":"T1074.001","name":"Local Data Staging","tactic":"collection"},{"id":"T1078","name":"Valid Accounts","tactic":"stealth"},{"id":"T1078.003","name":"Local Accounts","tactic":"stealth"},{"id":"T1082","name":"System Information Discovery","tactic":"discovery"},{"id":"T1083","name":"File and Directory Discovery","tactic":"discovery"},{"id":"T1087","name":"Account Discovery","tactic":"discovery"},{"id":"T1119","name":"Automated Collection","tactic":"collection"},{"id":"T1136.001","name":"Local Account","tactic":"persistence"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1213.006","name":"Databases","tactic":"collection"},{"id":"T1552.001","name":"Credentials In Files","tactic":"credential-access"},{"id":"T1567","name":"Exfiltration Over Web Service","tactic":"exfiltration"},{"id":"T1584.004","name":"Server","tactic":"resource-development"},{"id":"T1587.004","name":"Exploits","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1588.007","name":"Artificial Intelligence","tactic":"resource-development"},{"id":"T1590.004","name":"Network Topology","tactic":"reconnaissance"},{"id":"T1592.002","name":"Software","tactic":"reconnaissance"},{"id":"T1592.004","name":"Client Configurations","tactic":"reconnaissance"},{"id":"T1595.001","name":"Scanning IP Blocks","tactic":"reconnaissance"},{"id":"T1595.002","name":"Vulnerability Scanning","tactic":"reconnaissance"},{"id":"T1683","name":"Generate Content","tactic":"resource-development"}]', '[]', '[]', '["Government","Technology"]', '[]', '2026-04-20', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
--> statement-breakpoint
INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0021', 'c0021', 'C0021', 'C0021', 'https://attack.mitre.org/campaigns/C0021', 'C0021 was a spearphishing campaign conducted in November 2018 that targeted public sector institutions, non-governmental organizations (NGOs), educational institutions, and private-sector corporations in the oil and gas, chemical, and hospitality industries. The majority of targets were located in the US, particularly in and around Washington D.C., with other targets located in Europe, Hong Kong, India, and Canada. C0021''s technical artifacts, tactics, techniques, and procedures (TTPs), and targeting overlap with previous suspected APT29 activity.', '[]', '[{"id":"T1027.009","name":"Embedded Payloads","tactic":"stealth"},{"id":"T1027.010","name":"Command Obfuscation","tactic":"stealth"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1071.001","name":"Web Protocols","tactic":"command-and-control"},{"id":"T1095","name":"Non-Application Layer Protocol","tactic":"command-and-control"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1140","name":"Deobfuscate/Decode Files or Information","tactic":"stealth"},{"id":"T1204.001","name":"Malicious Link","tactic":"execution"},{"id":"T1218.011","name":"Rundll32","tactic":"stealth"},{"id":"T1566.002","name":"Spearphishing Link","tactic":"initial-access"},{"id":"T1573.002","name":"Asymmetric Cryptography","tactic":"command-and-control"},{"id":"T1583.001","name":"Domains","tactic":"resource-development"},{"id":"T1584.001","name":"Domains","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1608.001","name":"Upload Malware","tactic":"resource-development"}]', '["Cobalt Strike"]', '[]', '["Government","Education"]', '["Europe","United States"]', '2023-03-15', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
