INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0061', 'operation-digital-eye', 'Operation Digital Eye', 'C0061', 'https://attack.mitre.org/campaigns/C0061', 'Operation Digital Eye was conducted in June and July of 2024 by suspected People''s Republic of China (PRC)-nexus threat actors targeting business-to-business IT service providers in Southern Europe. Operation Digital Eye activity included the use of Visual Studio Code tunnels for command and control (C2) and custom lateral movement capabilities. Overlaps in tooling between Digital Eye and previous China-nexus campaigns, Operation Soft Cell and Operation Tainted Love, indicate the potential use of shared vendors or digital quartermasters.', '[]', '[{"id":"T1003.001","name":"LSASS Memory","tactic":"credential-access"},{"id":"T1003.002","name":"Security Account Manager","tactic":"credential-access"},{"id":"T1018","name":"Remote System Discovery","tactic":"discovery"},{"id":"T1021.001","name":"Remote Desktop Protocol","tactic":"lateral-movement"},{"id":"T1033","name":"System Owner/User Discovery","tactic":"discovery"},{"id":"T1036.005","name":"Match Legitimate Resource Name or Location","tactic":"stealth"},{"id":"T1059.003","name":"Windows Command Shell","tactic":"execution"},{"id":"T1069.001","name":"Local Groups","tactic":"discovery"},{"id":"T1070.004","name":"File Deletion","tactic":"stealth"},{"id":"T1087.001","name":"Local Account","tactic":"discovery"},{"id":"T1098.004","name":"SSH Authorized Keys","tactic":"persistence"},{"id":"T1106","name":"Native API","tactic":"execution"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1219.001","name":"IDE Tunneling","tactic":"command-and-control"},{"id":"T1505.003","name":"Web Shell","tactic":"persistence"},{"id":"T1543.003","name":"Windows Service","tactic":"persistence"},{"id":"T1550.002","name":"Pass the Hash","tactic":"lateral-movement"},{"id":"T1569.002","name":"Service Execution","tactic":"execution"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1591","name":"Gather Victim Org Information","tactic":"reconnaissance"},{"id":"T1614.001","name":"System Language Discovery","tactic":"discovery"},{"id":"T1665","name":"Hide Infrastructure","tactic":"command-and-control"}]', '["Mimikatz","PHPsert","Ping","sqlmap"]', '[]', '[]', '["Europe"]', '2026-04-19', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
