,"name":"System Time Discovery","tactic":"discovery"},{"id":"T1135","name":"Network Share Discovery","tactic":"discovery"},{"id":"T1204.002","name":"Malicious File","tactic":"execution"},{"id":"T1218.005","name":"Mshta","tactic":"stealth"},{"id":"T1218.010","name":"Regsvr32","tactic":"stealth"},{"id":"T1218.011","name":"Rundll32","tactic":"stealth"},{"id":"T1219.002","name":"Remote Desktop Software","tactic":"command-and-control"},{"id":"T1482","name":"Domain Trust Discovery","tactic":"discovery"},{"id":"T1486","name":"Data Encrypted for Impact","tactic":"impact"},{"id":"T1553.002","name":"Code Signing","tactic":"defense-impairment"},{"id":"T1566.001","name":"Spearphishing Attachment","tactic":"initial-access"},{"id":"T1567.002","name":"Exfiltration to Cloud Storage","tactic":"exfiltration"},{"id":"T1570","name":"Lateral Tool Transfer","tactic":"lateral-movement"},{"id":"T1588.001","name":"Malware","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"}]', '["AdFind","Bazar","Cobalt Strike","Conti","Rclone"]', '[]', '[]', '[]', '2022-09-29', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
