INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0023', 'operation-ghost', 'Operation Ghost', 'C0023', 'https://attack.mitre.org/campaigns/C0023', 'Operation Ghost was an APT29 campaign starting in 2013 that included operations against ministries of foreign affairs in Europe and the Washington, D.C. embassy of a European Union country. During Operation Ghost, APT29 used new families of malware and leveraged web services, steganography, and unique C2 infrastructure for each victim.', '["apt29"]', '[{"id":"T1001.002","name":"Steganography","tactic":"command-and-control"},{"id":"T1027.003","name":"Steganography","tactic":"stealth"},{"id":"T1078.002","name":"Domain Accounts","tactic":"stealth"},{"id":"T1102.002","name":"Bidirectional Communication","tactic":"command-and-control"},{"id":"T1546.003","name":"Windows Management Instrumentation Event Subscription","tactic":"privilege-escalation"},{"id":"T1583.001","name":"Domains","tactic":"resource-development"},{"id":"T1585.001","name":"Social Media Accounts","tactic":"resource-development"},{"id":"T1587.001","name":"Malware","tactic":"resource-development"}]', '["FatDuke","MiniDuke","PolyglotDuke","PsExec","RegDuke"]', '[]', '[]', '["Europe","United States"]', '2023-03-23', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
