INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0038', 'homeland-justice', 'HomeLand Justice', 'C0038', 'https://attack.mitre.org/campaigns/C0038', 'HomeLand Justice was a disruptive cyber campaign conducted by Iranian state-affiliated actors against Albanian government networks in July and September 2022. The activity combined ransomware, wiper malware, and data leak operations. Initial access for HomeLand Justice was established as early as May 2021, and threat actors moved laterally, exfiltrated sensitive information, and maintained persistence for approximately 14 months prior to the destructive phase of the operation. Responsibility was claimed by the "HomeLand Justice" front, which framed the campaign as retaliation against the Mujahedeen-e Khalq (MEK), an Iranian opposition group with a presence in Albania. Multiple Iran-nexus groups are assessed to have participated in the campaign, including HEXANE who probed victim infrastructure. A second wave of attacks was launched in September 2022 using similar tactics following public attribution of the previous activity to Iran and the severing of diplomatic ties between Iran and Albania.', '["void-manticore"]', '[{"id":"T1003.001","name":"LSASS Memory","tactic":"credential-access"},{"id":"T1021.001","name":"Remote Desktop Protocol","tactic":"lateral-movement"},{"id":"T1021.002","name":"SMB/Windows Admin Shares","tactic":"lateral-movement"},{"id":"T1036.005","name":"Match Legitimate Resource Name or Location","tactic":"stealth"},{"id":"T1041","name":"Exfiltration Over C2 Channel","tactic":"exfiltration"},{"id":"T1046","name":"Network Service Discovery","tactic":"discovery"},{"id":"T1047","name":"Windows Management Instrumentation","tactic":"execution"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1059.003","name":"Windows Command Shell","tactic":"execution"},{"id":"T1078","name":"Valid Accounts","tactic":"stealth"},{"id":"T1078.001","name":"Default Accounts","tactic":"stealth"},{"id":"T1087.003","name":"Email Account","tactic":"discovery"},{"id":"T1098.002","name":"Additional Email Delegate Permissions","tactic":"persistence"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1114.002","name":"Remote Email Collection","tactic":"collection"},{"id":"T1134.001","name":"Token Impersonation/Theft","tactic":"stealth"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1486","name":"Data Encrypted for Impact","tactic":"impact"},{"id":"T1505.003","name":"Web Shell","tactic":"persistence"},{"id":"T1561.002","name":"Disk Structure Wipe","tactic":"impact"},{"id":"T1570","name":"Lateral Tool Transfer","tactic":"lateral-movement"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1588.003","name":"Code Signing Certificates","tactic":"resource-development"},{"id":"T1685","name":"Disable or Modify Tools","tactic":"defense-impairment"},{"id":"T1685.001","name":"Disable or Modify Windows Event Log","tactic":"defense-impairment"}]', '["CHIMNEYSWEEP","Impacket","Mimikatz","ROADSWEEP","RawDisk","ZeroCleare","ftp"]', '["CVE-2019-0604"]', '["Government"]', '[]', '2024-08-06', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
