INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0032', 'c0032', 'C0032', 'C0032', 'https://attack.mitre.org/campaigns/C0032', 'C0032 was an extended campaign suspected to involve the Triton adversaries with related capabilities and techniques focused on gaining a foothold within IT environments. This campaign occurred in 2019 and was distinctly different from the Triton Safety Instrumented System Attack.', '["temp-veles"]', '[{"id":"T1003.001","name":"LSASS Memory","tactic":"credential-access"},{"id":"T1021.001","name":"Remote Desktop Protocol","tactic":"lateral-movement"},{"id":"T1021.004","name":"SSH","tactic":"lateral-movement"},{"id":"T1036.005","name":"Match Legitimate Resource Name or Location","tactic":"stealth"},{"id":"T1053.005","name":"Scheduled Task","tactic":"execution"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1070.004","name":"File Deletion","tactic":"stealth"},{"id":"T1070.006","name":"Timestomp","tactic":"stealth"},{"id":"T1074.001","name":"Local Data Staging","tactic":"collection"},{"id":"T1078","name":"Valid Accounts","tactic":"stealth"},{"id":"T1133","name":"External Remote Services","tactic":"persistence"},{"id":"T1505.003","name":"Web Shell","tactic":"persistence"},{"id":"T1546.012","name":"Image File Execution Options Injection","tactic":"privilege-escalation"},{"id":"T1571","name":"Non-Standard Port","tactic":"command-and-control"},{"id":"T1572","name":"Protocol Tunneling","tactic":"command-and-control"},{"id":"T1583.003","name":"Virtual Private Server","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"}]', '["Mimikatz"]', '[]', '[]', '[]', '2024-03-28', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
