INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0024', 'solarwinds-compromise', 'SolarWinds Compromise', 'C0024', 'https://attack.mitre.org/campaigns/C0024', 'The SolarWinds Compromise was a sophisticated supply chain cyber operation conducted by APT29 that was discovered in mid-December 2020. APT29 used customized malware to inject malicious code into the SolarWinds Orion software build process that was later distributed through a normal software update, they also used password spraying, token theft, API abuse, spear phishing, and other supply chain attacks to compromise user accounts and leverage their associated access. Victims of this campaign included government, consulting, technology, telecom, and other organizations in North America, Europe, Asia, and the Middle East. This activity has been labled the StellarParticle campaign in industry reporting. Industry reporting also initially referred to the actors involved in this campaign as UNC2452, NOBELIUM, Dark Halo, and SolarStorm. In April 2021, the US and UK governments attributed the SolarWinds Compromise to Russia''s Foreign Intelligence Service (SVR), public statements included citations to APT29, Cozy Bear, and The Dukes. The US government assessed that of the approximately 18,000 affected public and private sector customers of Solar Winds’ Orion product, a much smaller number were compromised by follow-on APT29 activity on their systems.', '["apt29"]', '[{"id":"T1003.006","name":"DCSync","tactic":"credential-access"},{"id":"T1005","name":"Data from Local System","tactic":"collection"},{"id":"T1016.001","name":"Internet Connection Discovery","tactic":"discovery"},{"id":"T1018","name":"Remote System Discovery","tactic":"discovery"},{"id":"T1021.001","name":"Remote Desktop Protocol","tactic":"lateral-movement"},{"id":"T1021.002","name":"SMB/Windows Admin Shares","tactic":"lateral-movement"},{"id":"T1021.006","name":"Windows Remote Management","tactic":"lateral-movement"},{"id":"T1036.004","name":"Masquerade Task or Service","tactic":"stealth"},{"id":"T1036.005","name":"Match Legitimate Resource Name or Location","tactic":"stealth"},{"id":"T1047","name":"Windows Management Instrumentation","tactic":"execution"},{"id":"T1048.002","name":"Exfiltration Over Asymmetric Encrypted Non-C2 Protocol","tactic":"exfiltration"},{"id":"T1053.005","name":"Scheduled Task","tactic":"execution"},{"id":"T1057","name":"Process Discovery","tactic":"discovery"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1059.003","name":"Windows Command Shell","tactic":"execution"},{"id":"T1059.005","name":"Visual Basic","tactic":"execution"},{"id":"T1069","name":"Permission Groups Discovery","tactic":"discovery"},{"id":"T1069.002","name":"Domain Groups","tactic":"discovery"},{"id":"T1070","name":"Indicator Removal","tactic":"stealth"},{"id":"T1070.004","name":"File Deletion","tactic":"stealth"},{"id":"T1070.006","name":"Timestomp","tactic":"stealth"},{"id":"T1070.008","name":"Clear Mailbox Data","tactic":"stealth"},{"id":"T1071.001","name":"Web Protocols","tactic":"command-and-control"},{"id":"T1074.002","name":"Remote Data Staging","tactic":"collection"},{"id":"T1078","name":"Valid Accounts","tactic":"stealth"},{"id":"T1078.002","name":"Domain Accounts","tactic":"stealth"},{"id":"T1078.003","name":"Local Accounts","tactic":"stealth"},{"id":"T1078.004","name":"Cloud Accounts","tactic":"stealth"},{"id":"T1083","name":"File and Directory Discovery","tactic":"discovery"},{"id":"T1087","name":"Account Discovery","tactic":"discovery"},{"id":"T1087.002","name":"Domain Account","tactic":"discovery"},{"id":"T1090.001","name":"Internal Proxy","tactic":"command-and-control"},{"id":"T1098.001","name":"Additional Cloud Credentials","tactic":"persistence"},{"id":"T1098.002","name":"Additional Email Delegate Per