Resolution","tactic":"command-and-control"},{"id":"T1583.001","name":"Domains","tactic":"resource-development"},{"id":"T1584.001","name":"Domains","tactic":"resource-development"},{"id":"T1587.001","name":"Malware","tactic":"resource-development"},{"id":"T1589.001","name":"Credentials","tactic":"reconnaissance"},{"id":"T1606.001","name":"Web Cookies","tactic":"credential-access"},{"id":"T1606.002","name":"SAML Tokens","tactic":"credential-access"},{"id":"T1665","name":"Hide Infrastructure","tactic":"command-and-control"},{"id":"T1680","name":"Local Storage Discovery","tactic":"discovery"},{"id":"T1685","name":"Disable or Modify Tools","tactic":"defense-impairment"},{"id":"T1685.001","name":"Disable or Modify Windows Event Log","tactic":"defense-impairment"},{"id":"T1686","name":"Disable or Modify System Firewall","tactic":"defense-impairment"}]', '["AdFind","Cobalt Strike","GoldFinder","GoldMax","Mimikatz","Raindrop","SUNBURST","SUNSPOT","Sibot","TEARDROP","TrailBlazer"]', '["CVE-2020-0688"]', '["Government","Telecom","Technology"]', '["Europe","Middle East","North America"]', '2023-03-24', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
