INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0036', 'pikabot-distribution-february-2024', 'Pikabot Distribution February 2024', 'C0036', 'https://attack.mitre.org/campaigns/C0036', 'Pikabot was distributed in Pikabot Distribution February 2024 using malicious emails with embedded links leading to malicious ZIP archives requiring user interaction for follow-on infection. The version of Pikabot distributed featured significant changes over the 2023 variant, including reduced code complexity and simplified obfuscation mechanisms.', '[]', '[{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1059.007","name":"JavaScript","tactic":"execution"},{"id":"T1566.002","name":"Spearphishing Link","tactic":"initial-access"},{"id":"T1574","name":"Hijack Execution Flow","tactic":"stealth"}]', '["Pikabot"]', '[]', '[]', '[]', '2024-07-17', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
