INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0052', 'spacehop-activity', 'SPACEHOP Activity', 'C0052', 'https://attack.mitre.org/campaigns/C0052', 'SPACEHOP Activity is conducted through commercially leased Virtual Private Servers (VPS), otherwise known as provisioned Operational Relay Box (ORB) networks. The network leveraged for SPACEHOP Activity enabled China-nexus cyber threat actors – such as APT5 and Ke3chang – to perform network reconnaissance scanning and vulnerability exploitation. SPACEHOP Activity has historically targeted entities in North America, Europe, and the Middle East.', '["ke3chang","apt5"]', '[{"id":"T1090.003","name":"Multi-hop Proxy","tactic":"command-and-control"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1583.003","name":"Virtual Private Server","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"}]', '[]', '["CVE-2022-27518"]', '["Space"]', '["Europe","Middle East","North America"]', '2025-03-25', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
