"T1566.002","name":"Spearphishing Link","tactic":"initial-access"},{"id":"T1585.002","name":"Email Accounts","tactic":"resource-development"},{"id":"T1585.003","name":"Cloud Accounts","tactic":"resource-development"},{"id":"T1586.002","name":"Email Accounts","tactic":"resource-development"},{"id":"T1587.001","name":"Malware","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1608.005","name":"Link Target","tactic":"resource-development"},{"id":"T1685.005","name":"Clear Windows Event Logs","tactic":"defense-impairment"}]', '["ANELLDR","Arp","AsyncRAT","FRP","HiddenFace","ROAMINGHOUSE","Rubeus","UPPERCUT"]', '[]', '[]', '["Europe"]', '2026-04-17', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
