INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0007', 'funnydream', 'FunnyDream', 'C0007', 'https://attack.mitre.org/campaigns/C0007', 'FunnyDream was a suspected Chinese cyber espionage campaign that targeted government and foreign organizations in Malaysia, the Philippines, Taiwan, Vietnam, and other parts of Southeast Asia. Security researchers linked the FunnyDream campaign to possible Chinese-speaking threat actors through the use of the Chinoxy backdoor and noted infrastructure overlap with the TAG-16 threat group.', '[]', '[{"id":"T1016","name":"System Network Configuration Discovery","tactic":"discovery"},{"id":"T1018","name":"Remote System Discovery","tactic":"discovery"},{"id":"T1047","name":"Windows Management Instrumentation","tactic":"execution"},{"id":"T1049","name":"System Network Connections Discovery","tactic":"discovery"},{"id":"T1057","name":"Process Discovery","tactic":"discovery"},{"id":"T1059.003","name":"Windows Command Shell","tactic":"execution"},{"id":"T1059.005","name":"Visual Basic","tactic":"execution"},{"id":"T1082","name":"System Information Discovery","tactic":"discovery"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1560.001","name":"Archive via Utility","tactic":"collection"},{"id":"T1583.001","name":"Domains","tactic":"resource-development"},{"id":"T1585.002","name":"Email Accounts","tactic":"resource-development"},{"id":"T1588.001","name":"Malware","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"}]', '["Chinoxy","FunnyDream","PcShare","Systeminfo","Tasklist","ccf32","ipconfig","netstat"]', '[]', '["Government"]', '["Southeast Asia"]', '2022-09-20', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
