INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0012', 'operation-cuckoobees', 'Operation CuckooBees', 'C0012', 'https://attack.mitre.org/campaigns/C0012', 'Operation CuckooBees was a cyber espionage campaign targeting technology and manufacturing companies in East Asia, Western Europe, and North America since at least 2019. Security researchers noted the goal of Operation CuckooBees, which was still ongoing as of May 2022, was likely the theft of proprietary information, research and development documents, source code, and blueprints for various technologies. Researchers assessed Operation CuckooBees was conducted by actors affiliated with Winnti Group, APT41, and BARIUM.', '[]', '[{"id":"T1003.002","name":"Security Account Manager","tactic":"credential-access"},{"id":"T1005","name":"Data from Local System","tactic":"collection"},{"id":"T1007","name":"System Service Discovery","tactic":"discovery"},{"id":"T1016","name":"System Network Configuration Discovery","tactic":"discovery"},{"id":"T1018","name":"Remote System Discovery","tactic":"discovery"},{"id":"T1027.010","name":"Command Obfuscation","tactic":"stealth"},{"id":"T1027.011","name":"Fileless Storage","tactic":"stealth"},{"id":"T1033","name":"System Owner/User Discovery","tactic":"discovery"},{"id":"T1036.005","name":"Match Legitimate Resource Name or Location","tactic":"stealth"},{"id":"T1049","name":"System Network Connections Discovery","tactic":"discovery"},{"id":"T1053.005","name":"Scheduled Task","tactic":"execution"},{"id":"T1057","name":"Process Discovery","tactic":"discovery"},{"id":"T1059.003","name":"Windows Command Shell","tactic":"execution"},{"id":"T1059.005","name":"Visual Basic","tactic":"execution"},{"id":"T1069.001","name":"Local Groups","tactic":"discovery"},{"id":"T1071.001","name":"Web Protocols","tactic":"command-and-control"},{"id":"T1078.002","name":"Domain Accounts","tactic":"stealth"},{"id":"T1082","name":"System Information Discovery","tactic":"discovery"},{"id":"T1083","name":"File and Directory Discovery","tactic":"discovery"},{"id":"T1087.001","name":"Local Account","tactic":"discovery"},{"id":"T1087.002","name":"Domain Account","tactic":"discovery"},{"id":"T1120","name":"Peripheral Device Discovery","tactic":"discovery"},{"id":"T1124","name":"System Time Discovery","tactic":"discovery"},{"id":"T1133","name":"External Remote Services","tactic":"persistence"},{"id":"T1135","name":"Network Share Discovery","tactic":"discovery"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1201","name":"Password Policy Discovery","tactic":"discovery"},{"id":"T1505.003","name":"Web Shell","tactic":"persistence"},{"id":"T1543.003","name":"Windows Service","tactic":"persistence"},{"id":"T1547.006","name":"Kernel Modules and Extensions","tactic":"persistence"},{"id":"T1560.001","name":"Archive via Utility","tactic":"collection"},{"id":"T1574.001","name":"DLL","tactic":"stealth"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"}]', '["Systeminfo","dsquery"]', '[]', '["Technology","Manufacturing"]', '["Europe","North America"]', '2022-09-22', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
