INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0059', 'salesforce-data-exfiltration', 'Salesforce Data Exfiltration', 'C0059', 'https://attack.mitre.org/campaigns/C0059', 'The Salesforce Data Exfiltration campaign began in October 2024 with financially-motivated threat actor UNC6040 using Spearphishing Voice (vishing) to compromise corporate Salesforce instances for large-scale data theft and extortion. Following the initial data theft, victim organizations received extortion demands from a separate threat actor, UNC6240, who claimed to be the “ShinyHunters” group. The observed infrastructure and TTPs used during the Salesforce Data Exfiltration campaign overlap with those used by threat groups with suspected ties to the broader collective known as "The Com.” These overlaps could plausibly be the result of associated actors operating within the same communities and are not necessarily an indication of a direct operational relationship.', '[]', '[{"id":"T1020","name":"Automated Exfiltration","tactic":"exfiltration"},{"id":"T1036","name":"Masquerading","tactic":"stealth"},{"id":"T1059.006","name":"Python","tactic":"execution"},{"id":"T1078.002","name":"Domain Accounts","tactic":"stealth"},{"id":"T1083","name":"File and Directory Discovery","tactic":"discovery"},{"id":"T1090","name":"Proxy","tactic":"command-and-control"},{"id":"T1090.003","name":"Multi-hop Proxy","tactic":"command-and-control"},{"id":"T1213.004","name":"Customer Relationship Management Software","tactic":"collection"},{"id":"T1567","name":"Exfiltration Over Web Service","tactic":"exfiltration"},{"id":"T1585","name":"Establish Accounts","tactic":"resource-development"},{"id":"T1585.002","name":"Email Accounts","tactic":"resource-development"},{"id":"T1586.002","name":"Email Accounts","tactic":"resource-development"},{"id":"T1587.001","name":"Malware","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1598.004","name":"Spearphishing Voice","tactic":"reconnaissance"},{"id":"T1608.005","name":"Link Target","tactic":"resource-development"},{"id":"T1671","name":"Cloud Application Integration","tactic":"persistence"},{"id":"T1684.001","name":"Impersonation","tactic":"stealth"}]', '["Tor"]', '[]', '[]', '[]', '2025-10-22', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
