INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0051', 'apt28-nearest-neighbor-campaign', 'APT28 Nearest Neighbor Campaign', 'C0051', 'https://attack.mitre.org/campaigns/C0051', 'APT28 Nearest Neighbor Campaign was conducted by APT28 from early February 2022 to November 2024 against organizations and individuals with expertise on Ukraine. APT28 primarily leveraged living-off-the-land techniques, while leveraging the zero-day exploitation of CVE-2022-38028. Notably, APT28 leveraged Wi-Fi networks in close proximity to the intended target to gain initial access to the victim environment. By daisy-chaining multiple compromised organizations nearby the intended target, APT28 discovered dual-homed systems (with both a wired and wireless network connection) to enable Wi-Fi and use compromised credentials to connect to the victim network.', '["apt28"]', '[{"id":"T1003.002","name":"Security Account Manager","tactic":"credential-access"},{"id":"T1003.003","name":"NTDS","tactic":"credential-access"},{"id":"T1006","name":"Direct Volume Access","tactic":"stealth"},{"id":"T1016.002","name":"Wi-Fi Discovery","tactic":"discovery"},{"id":"T1021.001","name":"Remote Desktop Protocol","tactic":"lateral-movement"},{"id":"T1021.002","name":"SMB/Windows Admin Shares","tactic":"lateral-movement"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1059.003","name":"Windows Command Shell","tactic":"execution"},{"id":"T1074.001","name":"Local Data Staging","tactic":"collection"},{"id":"T1090.001","name":"Internal Proxy","tactic":"command-and-control"},{"id":"T1110.003","name":"Password Spraying","tactic":"credential-access"},{"id":"T1140","name":"Deobfuscate/Decode Files or Information","tactic":"stealth"},{"id":"T1560.001","name":"Archive via Utility","tactic":"collection"},{"id":"T1561.001","name":"Disk Content Wipe","tactic":"impact"},{"id":"T1567","name":"Exfiltration Over Web Service","tactic":"exfiltration"},{"id":"T1584","name":"Compromise Infrastructure","tactic":"resource-development"},{"id":"T1669","name":"Wi-Fi Networks","tactic":"initial-access"},{"id":"T1686.003","name":"Windows Host Firewall","tactic":"defense-impairment"}]', '["cipher.exe","netsh"]', '["CVE-2022-38028"]', '[]', '[]', '2025-02-25', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
--> statement-breakpoint
INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0042', 'outer-space', 'Outer Space', 'C0042', 'https://attack.mitre.org/campaigns/C0042', 'Outer Space was a campaign conducted by OilRig throughout 2021 that used the SampleCheck5000 downloader and Solar backdoor to target Israeli organizations.', '["oilrig"]', '[{"id":"T1027.013","name":"Encrypted/Encoded File","tactic":"stealth"},{"id":"T1059.005","name":"Visual Basic","tactic":"execution"},{"id":"T1071.001","name":"Web Protocols","tactic":"command-and-control"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1217","name":"Browser Information Discovery","tactic":"discovery"},{"id":"T1584.004","name":"Server","tactic":"resource-development"},{"id":"T1585.003","name":"Cloud Accounts","tactic":"resource-development"},{"id":"T1587.001","name":"Malware","tactic":"resource-development"}]', '["SampleCheck5000","Solar"]', '[]', '["Space"]', '[]', '2024-11-21', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
