INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0046', 'arcanedoor', 'ArcaneDoor', 'C0046', 'https://attack.mitre.org/campaigns/C0046', 'ArcaneDoor is a campaign targeting networking devices from Cisco and other vendors between July 2023 and April 2024, primarily focused on government and critical infrastructure networks. ArcaneDoor is associated with the deployment of the custom backdoors Line Runner and Line Dancer. ArcaneDoor is attributed to a group referred to as UAT4356 or STORM-1849, and is assessed to be a state-sponsored campaign.', '[]', '[{"id":"T1014","name":"Rootkit","tactic":"stealth"},{"id":"T1020","name":"Automated Exfiltration","tactic":"exfiltration"},{"id":"T1036","name":"Masquerading","tactic":"stealth"},{"id":"T1037","name":"Boot or Logon Initialization Scripts","tactic":"persistence"},{"id":"T1040","name":"Network Sniffing","tactic":"credential-access"},{"id":"T1041","name":"Exfiltration Over C2 Channel","tactic":"exfiltration"},{"id":"T1055","name":"Process Injection","tactic":"stealth"},{"id":"T1059","name":"Command and Scripting Interpreter","tactic":"execution"},{"id":"T1070.004","name":"File Deletion","tactic":"stealth"},{"id":"T1071.001","name":"Web Protocols","tactic":"command-and-control"},{"id":"T1082","name":"System Information Discovery","tactic":"discovery"},{"id":"T1102.003","name":"One-Way Communication","tactic":"command-and-control"},{"id":"T1119","name":"Automated Collection","tactic":"collection"},{"id":"T1133","name":"External Remote Services","tactic":"persistence"},{"id":"T1140","name":"Deobfuscate/Decode Files or Information","tactic":"stealth"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1556","name":"Modify Authentication Process","tactic":"defense-impairment"},{"id":"T1557","name":"Adversary-in-the-Middle","tactic":"credential-access"},{"id":"T1583.003","name":"Virtual Private Server","tactic":"resource-development"},{"id":"T1583.006","name":"Web Services","tactic":"resource-development"},{"id":"T1587.001","name":"Malware","tactic":"resource-development"},{"id":"T1587.003","name":"Digital Certificates","tactic":"resource-development"},{"id":"T1653","name":"Power Settings","tactic":"persistence"},{"id":"T1685","name":"Disable or Modify Tools","tactic":"defense-impairment"},{"id":"T1690","name":"Prevent Command History Logging","tactic":"defense-impairment"}]', '["Line Dancer","Line Runner"]', '["CVE-2024-20353"]', '["Government"]', '[]', '2025-01-06', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
--> statement-breakpoint
INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0063', '2025-poland-wiper-attacks', '2025 Poland Wiper Attacks', 'C0063', 'https://attack.mitre.org/campaigns/C0063', '2025 Poland Wiper Attacks is a Russian state-sponsored campaign that conducted destructive cyberattacks against Polish energy infrastructure in December 2025. Targets included more than 30 wind and photovoltaic farms, a combined heat and power (CHP) plant, and a manufacturing sector company. The attacks on the distributed energy resources (DER) disrupted communications between affected facilities and the distribution system operator, but did not impact electricity generation or heat supply. Across the campaign, threat actors deployed two previously undocumented wiper tools, DynoWiper, a Windows-based wiper and LazyWiper, a PowerShell wiper, distributed via malicious Group Policy Objects. At the CHP plant, threat actors had maintained access since at least March 2025, using that foothold to obtain credentials and move laterally before attempting wiper deployment. Some reporting has assessed the activity to be consistent with Russian Federal Security Service (FSB) threat activity group Dragonfly, also tracked as STATIC TUNDRA, while other reporting attributes the destructive wiper activities to the Russian General Staff Main Intelligence Directorate (GRU) threat activity group ELECTRUM, also tracked as Sandworm Team.', '[]', '[{"id":"T1003.001","name":"LSASS Memory","tactic":"credential-access"},{"id":"T1003.002","name":"Security Account Manager","tactic":"credential-access"},{"id":"T1003.003","name":"NTDS","tactic":"credential-access"},{"id":"T1006","name":"Direct Volume Access","tactic":"stealth"},{"id":"T1016","name":"System Network Configuration Discovery","tactic":"discovery"},{"id":"T1021.001","name":"Remote Desktop Protocol","tactic":"lateral-movement"},{"id":"T1027.013","name":"Encrypted/Encoded File","tactic":"stealth"},{"id":"T1036.005","name":"Match Legitimate Resource Name or Location","tactic":"stealth"},{"id":"T1046","name":"Network Service Discovery","tactic":"discovery"},{"id":"T1048.003","name":"Exfiltration Over Unencrypted Non-C2 Protocol","tactic":"exfiltration"},{"id":"T1049","name":"System Network Connections Discovery","tactic":"discovery"},{"id":"T1053","name":"Scheduled Task/Job","tactic":"execution"},{"id":"T1057","name":"Process Discovery","tactic":"discovery"},{"id":"T1059.003","name":"Windows Command Shell","tactic":"execution"},{"id":"T1059.004","name":"Unix Shell","tactic":"execution"},{"id":"T1059.008","name":"Network Device CLI","tactic":"execution"},{"id":"T1074.001","name":"Local Data Staging","tactic":"collection"},{"id":"T1078.002","name":"Domain Accounts","tactic":"stealth"},{"id":"T1078.004","name":"Cloud Accounts","tactic":"stealth"},{"id":"T1083","name":"File and Directory Discovery","tactic":"discovery"},{"id":"T1090","name":"Proxy","tactic":"command-and-control"},{"id":"T1090.003","name":"Multi-hop Proxy","tactic":"command-and-control"},{"id":"T1102.002","name":"Bidirectional Communication","tactic":"command-and-control"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1110.002","name":"Password Cracking","tactic":"credential-access"},{"id":"T1113","name":"Screen Capture","tactic":"collection"},{"id":"T1114.002","name":"Remote Email Collection","tactic":"collection"},{"id":"T1133","name":"External Remote Services","tactic":"persistence"},{"id":"T1140","name":"Deobfuscate/Decode Files or Information","tactic":"stealth"},{"id":"T1484.001","name":"Group Policy Modification","tactic":"defense-impairment"},{"id":"T1485","name":"Data Destruction","tactic":"impact"},{"id":"T1490","name":"Inhibit System Recovery","tactic":"impact"},{"id":"T1495","name":"Firmware Corruption","tactic":"impact"},{"id":"T1529","name":"System Shutdown/Reboot","tactic":"impact"},{"id":"T1530","name":"Data from Cloud Storage","tactic":"collection"},{"id":"T1550.002","name":"Pass the Hash","tactic":"lateral-movement"},{"id":"T1555","name":"Credentials from Password Stores","tactic":"credential-access"},{"id":"T1556.006","name":"Multi-Factor Authentication","tactic":"defense-impairment"},{"id":"T1558","name":"Steal or Forge Kerberos Tickets","tactic":"credential-access"},{"id":"T1560.001","name":"Archive via Utility","tactic":"collection"},{"id":"T1567.004","name":"Exfiltration Over Webhook","tactic":"exfiltration"},{"id":"T1570","name":"Lateral Tool Transfer","tactic":"lateral-movement"},{"id":"T1571","name":"Non-Standard Port","tactic":"command-and-control"},{"id":"T1583.006","name":"Web Services","tactic":"resource-development"},{"id":"T1584.001","name":"Domains","tactic":"resource-development"},{"id":"T1584.003","name":"Virtual Private Server","tactic":"resource-development"},{"id":"T1584.008","name":"Network Devices","tactic":"resource-development"},{"id":"T1587.001","name":"Malware","tactic":"resource-development"},{"id":"T1588.007","name":"Artificial Intelligence","tactic":"resource-development"},{"id":"T1590.006","name":"Network Security Appliances","tactic":"reconnaissance"},{"id":"T1602.002","name":"Network Device Configuration Dump","tactic":"collection"},{"id":"T1608.002","name":"Upload Tool","tactic":"resource-development"},{"id":"T1686.002","name":"Network Device Firewall","tactic":"defense-impairment"}]', '["Arp","DynoWiper","Impacket","LazyWiper","Ping","PsExec","Rubeus","Tasklist","Tor","certutil","netstat"]', '[]', '["Energy","Manufacturing"]', '[]', '2026-04-22', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
