INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0033', 'c0033', 'C0033', 'C0033', 'https://attack.mitre.org/campaigns/C0033', 'C0033 was a PROMETHIUM campaign during which they used StrongPity to target Android users. C0033 was the first publicly documented mobile campaign for PROMETHIUM, who previously used Windows-based techniques.', '["promethium"]', '[]', '["StrongPity"]', '[]', '[]', '[]', '2024-03-28', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
