c":"persistence"},{"id":"T1570","name":"Lateral Tool Transfer","tactic":"lateral-movement"},{"id":"T1685.001","name":"Disable or Modify Windows Event Log","tactic":"defense-impairment"}]', '["Industroyer"]', '[]', '[]', '[]', '2023-03-31', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
