588.003","name":"Code Signing Certificates","tactic":"resource-development"},{"id":"T1593.002","name":"Search Engines","tactic":"reconnaissance"},{"id":"T1594","name":"Search Victim-Owned Websites","tactic":"reconnaissance"},{"id":"T1596.005","name":"Scan Databases","tactic":"reconnaissance"}]', '["Cobalt Strike","DUSTPAN","DUSTTRAP","certutil"]', '[]', '["Media"]', '["Europe","Middle East"]', '2024-09-16', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
