INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0002', 'night-dragon-c0002', 'Night Dragon', 'C0002', 'https://attack.mitre.org/campaigns/C0002', 'Night Dragon was a cyber espionage campaign that targeted oil, energy, and petrochemical companies, along with individuals and executives in Kazakhstan, Taiwan, Greece, and the United States. The unidentified threat actors searched for information related to oil and gas field production systems, financials, and collected data from SCADA systems. Based on the observed techniques, tools, and network activities, security researchers assessed the campaign involved a threat group based in China.', '[]', '[{"id":"T1003.002","name":"Security Account Manager","tactic":"credential-access"},{"id":"T1005","name":"Data from Local System","tactic":"collection"},{"id":"T1008","name":"Fallback Channels","tactic":"command-and-control"},{"id":"T1027.002","name":"Software Packing","tactic":"stealth"},{"id":"T1027.013","name":"Encrypted/Encoded File","tactic":"stealth"},{"id":"T1033","name":"System Owner/User Discovery","tactic":"discovery"},{"id":"T1059.003","name":"Windows Command Shell","tactic":"execution"},{"id":"T1071.001","name":"Web Protocols","tactic":"command-and-control"},{"id":"T1074.002","name":"Remote Data Staging","tactic":"collection"},{"id":"T1078","name":"Valid Accounts","tactic":"stealth"},{"id":"T1078.002","name":"Domain Accounts","tactic":"stealth"},{"id":"T1083","name":"File and Directory Discovery","tactic":"discovery"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1110.002","name":"Password Cracking","tactic":"credential-access"},{"id":"T1112","name":"Modify Registry","tactic":"defense-impairment"},{"id":"T1114.001","name":"Local Email Collection","tactic":"collection"},{"id":"T1133","name":"External Remote Services","tactic":"persistence"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1204.001","name":"Malicious Link","tactic":"execution"},{"id":"T1219","name":"Remote Access Tools","tactic":"command-and-control"},{"id":"T1550.002","name":"Pass the Hash","tactic":"lateral-movement"},{"id":"T1566.002","name":"Spearphishing Link","tactic":"initial-access"},{"id":"T1568","name":"Dynamic Resolution","tactic":"command-and-control"},{"id":"T1583.004","name":"Server","tactic":"resource-development"},{"id":"T1584.004","name":"Server","tactic":"resource-development"},{"id":"T1588.001","name":"Malware","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1608.001","name":"Upload Malware","tactic":"resource-development"},{"id":"T1685","name":"Disable or Modify Tools","tactic":"defense-impairment"}]', '["ASPXSpy","PsExec","at","gsecdump","zwShell"]', '[]', '["Energy"]', '["United States"]', '2022-09-08', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
