INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0039', 'versa-director-zero-day-exploitation', 'Versa Director Zero Day Exploitation', 'C0039', 'https://attack.mitre.org/campaigns/C0039', 'Versa Director Zero Day Exploitation was conducted by Volt Typhoon from early June through August 2024 as zero-day exploitation of Versa Director servers controlling software-defined wide area network (SD-WAN) applications. Since tracked as CVE-2024-39717, exploitation focused on credential capture from compromised Versa Director servers at managed service providers (MSPs) and internet service providers (ISPs) to enable follow-on access to service provider clients. Versa Director Zero Day Exploitation was followed by the delivery of the VersaMem web shell for both credential theft and follow-on code execution.', '["volt-typhoon"]', '[{"id":"T1056","name":"Input Capture","tactic":"collection"},{"id":"T1071.001","name":"Web Protocols","tactic":"command-and-control"},{"id":"T1095","name":"Non-Application Layer Protocol","tactic":"command-and-control"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1505.003","name":"Web Shell","tactic":"persistence"},{"id":"T1573.002","name":"Asymmetric Cryptography","tactic":"command-and-control"},{"id":"T1584.008","name":"Network Devices","tactic":"resource-development"},{"id":"T1587.001","name":"Malware","tactic":"resource-development"}]', '["VersaMem"]', '["CVE-2024-39717"]', '[]', '[]', '2024-08-27', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
--> statement-breakpoint
INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0014', 'operation-wocao-c0014', 'Operation Wocao', 'C0014', 'https://attack.mitre.org/campaigns/C0014', 'Operation Wocao was a cyber espionage campaign that targeted organizations around the world, including in Brazil, China, France, Germany, Italy, Mexico, Portugal, Spain, the United Kingdom, and the United States. The suspected China-based actors compromised government organizations and managed service providers, as well as aviation, construction, energy, finance, health care, insurance, offshore engineering, software development, and transportation companies. Security researchers assessed the Operation Wocao actors used similar TTPs and tools as APT20, suggesting a possible overlap. Operation Wocao was named after an observed command line entry by one of the threat actors, possibly out of frustration from losing webshell access.', '[]', '[{"id":"T1001","name":"Data Obfuscation","tactic":"command-and-control"},{"id":"T1003.001","name":"LSASS Memory","tactic":"credential-access"},{"id":"T1003.006","name":"DCSync","tactic":"credential-access"},{"id":"T1005","name":"Data from Local System","tactic":"collection"},{"id":"T1007","name":"System Service Discovery","tactic":"discovery"},{"id":"T1012","name":"Query Registry","tactic":"discovery"},{"id":"T1016","name":"System Network Configuration Discovery","tactic":"discovery"},{"id":"T1016.001","name":"Internet Connection Discovery","tactic":"discovery"},{"id":"T1018","name":"Remote System Discovery","tactic":"discovery"},{"id":"T1021.002","name":"SMB/Windows Admin Shares","tactic":"lateral-movement"},{"id":"T1027.005","name":"Indicator Removal from Tools","tactic":"stealth"},{"id":"T1027.010","name":"Command Obfuscation","tactic":"stealth"},{"id":"T1033","name":"System Owner/User Discovery","tactic":"discovery"},{"id":"T1036.005","name":"Match Legitimate Resource Name or Location","tactic":"stealth"},{"id":"T1041","name":"Exfiltration Over C2 Channel","tactic":"exfiltration"},{"id":"T1046","name":"Network Service Discovery","tactic":"discovery"},{"id":"T1047","name":"Windows Management Instrumentation","tactic":"execution"},{"id":"T1049","name":"System Network Connections Discovery","tactic":"discovery"},{"id":"T1053.005","name":"Scheduled Task","tactic":"execution"},{"id":"T1055","name":"Process Injection","tactic":"stealth"},{"id":"T1056.001","name":"Keylogging","tactic":"collection"},{"id":"T1057","name":"Process Discovery","tactic":"discovery"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1059.003","name":"Windows Command Shell","tactic":"execution"},{"id":"T1059.005","name":"Visual Basic","tactic":"execution"},{"id":"T1059.006","name":"Python","tactic":"execution"},{"id":"T1069.001","name":"Local Groups","tactic":"discovery"},{"id":"T1070.004","name":"File Deletion","tactic":"stealth"},{"id":"T1071.001","name":"Web Protocols","tactic":"command-and-control"},{"id":"T1074.001","name":"Local Data Staging","tactic":"collection"},{"id":"T1078","name":"Valid Accounts","tactic":"stealth"},{"id":"T1078.002","name":"Domain Accounts","tactic":"stealth"},{"id":"T1078.003","name":"Local Accounts","tactic":"stealth"},{"id":"T1082","name":"System Information Discovery","tactic":"discovery"},{"id":"T1083","name":"File and Directory Discovery","tactic":"discovery"},{"id":"T1087.002","name":"Domain Account","tactic":"discovery"},{"id":"T1090","name":"Proxy","tactic":"command-and-control"},{"id":"T1090.001","name":"Internal Proxy","tactic":"command-and-control"},{"id":"T1090.003","name":"Multi-hop Proxy","tactic":"command-and-control"},{"id":"T1095","name":"Non-Application Layer Protocol","tactic":"command-and-control"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1106","name":"Native API","tactic":"execution"},{"id":"T1111","name":"Multi-Factor Authentication Interception","tactic":"credential-access"},{"id":"T1112","name":"Modify Registry","tactic":"defense-impairment"},{"id":"T1115","name":"Clipboard Data","tactic":"collection"},{"id":"T1119","name":"Automated Collection","tactic":"collection"},{"id":"T1120","name":"Peripheral Device Discovery","tactic":"discovery"},{"id":"T1124","name":"System Time Discovery","tactic":"discovery"},{"id":"T1133","name":"External Remote Services","tactic":"persistence"},{"id":"T1135","name":"Network Share Discovery","tactic":"discovery"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1505.003","name":"Web Shell","tactic":"persistence"},{"id":"T1518","name":"Software Discovery","tactic":"discovery"},{"id":"T1518.001","name":"Security Software Discovery","tactic":"discovery"},{"id":"T1552.004","name":"Private Keys","tactic":"credential-access"},{"id":"T1555.005","name":"Password Managers","tactic":"credential-access"},{"id":"T1558.003","name":"Kerberoasting","tactic":"credential-access"},{"id":"T1560.001","name":"Archive via Utility","tactic":"collection"},{"id":"T1569.002","name":"Service Execution","tactic":"execution"},{"id":"T1570","name":"Lateral Tool Transfer","tactic":"lateral-movement"},{"id":"T1571","name":"Non-Standard Port","tactic":"command-and-control"},{"id":"T1573.002","name":"Asymmetric Cryptography","tactic":"command-and-control"},{"id":"T1583.004","name":"Server","tactic":"resource-development"},{"id":"T1585.002","name":"Email Accounts","tactic":"resource-development"},{"id":"T1587.001","name":"Malware","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1589","name":"Gather Victim Identity Information","tactic":"reconnaissance"},{"id":"T1680","name":"Local Storage Discovery","tactic":"discovery"},{"id":"T1685.005","name":"Clear Windows Event Logs","tactic":"defense-impairment"},{"id":"T1686.003","name":"Windows Host Firewall","tactic":"defense-impairment"}]', '["BloodHound","Impacket","Mimikatz","PowerSploit","PsExec","Tor","Wevtutil","dsquery","netstat"]', '[]', '["Government","Finance","Energy","Transportation","Aviation"]', '["United States"]', '2022-09-27', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
