INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0049', 'leviathan-australian-intrusions', 'Leviathan Australian Intrusions', 'C0049', 'https://attack.mitre.org/campaigns/C0049', 'Leviathan Australian Intrusions consisted of at least two long-term intrusions against victims in Australia by Leviathan, relying on similar tradecraft such as external service exploitation followed by extensive credential capture and re-use to enable privilege escalation and lateral movement. Leviathan Australian Intrusions were focused on exfiltrating sensitive data including valid credentials for the victim organizations.', '["leviathan"]', '[{"id":"T1018","name":"Remote System Discovery","tactic":"discovery"},{"id":"T1021.002","name":"SMB/Windows Admin Shares","tactic":"lateral-movement"},{"id":"T1021.004","name":"SSH","tactic":"lateral-movement"},{"id":"T1041","name":"Exfiltration Over C2 Channel","tactic":"exfiltration"},{"id":"T1056","name":"Input Capture","tactic":"collection"},{"id":"T1068","name":"Exploitation for Privilege Escalation","tactic":"privilege-escalation"},{"id":"T1074.001","name":"Local Data Staging","tactic":"collection"},{"id":"T1078","name":"Valid Accounts","tactic":"stealth"},{"id":"T1078.002","name":"Domain Accounts","tactic":"stealth"},{"id":"T1078.003","name":"Local Accounts","tactic":"stealth"},{"id":"T1082","name":"System Information Discovery","tactic":"discovery"},{"id":"T1111","name":"Multi-Factor Authentication Interception","tactic":"credential-access"},{"id":"T1135","name":"Network Share Discovery","tactic":"discovery"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1212","name":"Exploitation for Credential Access","tactic":"credential-access"},{"id":"T1213.006","name":"Databases","tactic":"collection"},{"id":"T1482","name":"Domain Trust Discovery","tactic":"discovery"},{"id":"T1505.003","name":"Web Shell","tactic":"persistence"},{"id":"T1528","name":"Steal Application Access Token","tactic":"credential-access"},{"id":"T1552","name":"Unsecured Credentials","tactic":"credential-access"},{"id":"T1552.001","name":"Credentials In Files","tactic":"credential-access"},{"id":"T1558.003","name":"Kerberoasting","tactic":"credential-access"},{"id":"T1588.006","name":"Vulnerabilities","tactic":"resource-development"},{"id":"T1594","name":"Search Victim-Owned Websites","tactic":"reconnaissance"},{"id":"T1615","name":"Group Policy Discovery","tactic":"discovery"},{"id":"T1686","name":"Disable or Modify System Firewall","tactic":"defense-impairment"}]', '[]', '[]', '[]', '[]', '2025-02-03', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
