INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0017', 'c0017', 'C0017', 'C0017', 'https://attack.mitre.org/campaigns/C0017', 'C0017 was an APT41 campaign conducted between May 2021 and February 2022 that successfully compromised at least six U.S. state government networks through the exploitation of vulnerable Internet facing web applications. During C0017, APT41 was quick to adapt and use publicly-disclosed as well as zero-day vulnerabilities for initial access, and in at least two cases re-compromised victims following remediation efforts. The goals of C0017 are unknown, however APT41 was observed exfiltrating Personal Identifiable Information (PII).', '["apt41"]', '[{"id":"T1001.003","name":"Protocol or Service Impersonation","tactic":"command-and-control"},{"id":"T1003.002","name":"Security Account Manager","tactic":"credential-access"},{"id":"T1005","name":"Data from Local System","tactic":"collection"},{"id":"T1016","name":"System Network Configuration Discovery","tactic":"discovery"},{"id":"T1027","name":"Obfuscated Files or Information","tactic":"stealth"},{"id":"T1027.002","name":"Software Packing","tactic":"stealth"},{"id":"T1033","name":"System Owner/User Discovery","tactic":"discovery"},{"id":"T1036.004","name":"Masquerade Task or Service","tactic":"stealth"},{"id":"T1036.005","name":"Match Legitimate Resource Name or Location","tactic":"stealth"},{"id":"T1041","name":"Exfiltration Over C2 Channel","tactic":"exfiltration"},{"id":"T1048.003","name":"Exfiltration Over Unencrypted Non-C2 Protocol","tactic":"exfiltration"},{"id":"T1053.005","name":"Scheduled Task","tactic":"execution"},{"id":"T1059.003","name":"Windows Command Shell","tactic":"execution"},{"id":"T1059.007","name":"JavaScript","tactic":"execution"},{"id":"T1071.001","name":"Web Protocols","tactic":"command-and-control"},{"id":"T1074.001","name":"Local Data Staging","tactic":"collection"},{"id":"T1090","name":"Proxy","tactic":"command-and-control"},{"id":"T1102","name":"Web Service","tactic":"command-and-control"},{"id":"T1102.001","name":"Dead Drop Resolver","tactic":"command-and-control"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1134","name":"Access Token Manipulation","tactic":"stealth"},{"id":"T1140","name":"Deobfuscate/Decode Files or Information","tactic":"stealth"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1505.003","name":"Web Shell","tactic":"persistence"},{"id":"T1560.003","name":"Archive via Custom Method","tactic":"collection"},{"id":"T1567","name":"Exfiltration Over Web Service","tactic":"exfiltration"},{"id":"T1574","name":"Hijack Execution Flow","tactic":"stealth"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1680","name":"Local Storage Discovery","tactic":"discovery"}]', '["Cobalt Strike","DEADEYE","KEYPLUG","Mimikatz","Ping","dsquery"]', '["CVE-2021-44207","CVE-2021-44228"]', '["Government","Media"]', '[]', '2022-12-01', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
