INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0027', 'c0027', 'C0027', 'C0027', 'https://attack.mitre.org/campaigns/C0027', 'C0027 was a financially-motivated campaign linked to Scattered Spider that targeted telecommunications and business process outsourcing (BPO) companies from at least June through December of 2022. During C0027 Scattered Spider used various forms of social engineering, performed SIM swapping, and attempted to leverage access from victim environments to mobile carrier networks.', '["scattered-spider"]', '[{"id":"T1003.006","name":"DCSync","tactic":"credential-access"},{"id":"T1021.007","name":"Cloud Services","tactic":"lateral-movement"},{"id":"T1046","name":"Network Service Discovery","tactic":"discovery"},{"id":"T1047","name":"Windows Management Instrumentation","tactic":"execution"},{"id":"T1069.003","name":"Cloud Groups","tactic":"discovery"},{"id":"T1078.004","name":"Cloud Accounts","tactic":"stealth"},{"id":"T1087.003","name":"Email Account","tactic":"discovery"},{"id":"T1087.004","name":"Cloud Account","tactic":"discovery"},{"id":"T1090","name":"Proxy","tactic":"command-and-control"},{"id":"T1098.001","name":"Additional Cloud Credentials","tactic":"persistence"},{"id":"T1098.003","name":"Additional Cloud Roles","tactic":"persistence"},{"id":"T1098.005","name":"Device Registration","tactic":"persistence"},{"id":"T1102","name":"Web Service","tactic":"command-and-control"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1133","name":"External Remote Services","tactic":"persistence"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1213.002","name":"Sharepoint","tactic":"collection"},{"id":"T1219.002","name":"Remote Desktop Software","tactic":"command-and-control"},{"id":"T1530","name":"Data from Cloud Storage","tactic":"collection"},{"id":"T1566.004","name":"Spearphishing Voice","tactic":"initial-access"},{"id":"T1572","name":"Protocol Tunneling","tactic":"command-and-control"},{"id":"T1578.002","name":"Create Cloud Instance","tactic":"defense-impairment"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"},{"id":"T1589.001","name":"Credentials","tactic":"reconnaissance"},{"id":"T1598.001","name":"Spearphishing Service","tactic":"reconnaissance"},{"id":"T1598.004","name":"Spearphishing Voice","tactic":"reconnaissance"},{"id":"T1621","name":"Multi-Factor Authentication Request Generation","tactic":"credential-access"},{"id":"T1684.001","name":"Impersonation","tactic":"stealth"}]', '["Impacket"]', '["CVE-2021-35464"]', '["Telecom"]', '[]', '2023-06-30', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
