INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0034', '2022-ukraine-electric-power-attack', '2022 Ukraine Electric Power Attack', 'C0034', 'https://attack.mitre.org/campaigns/C0034', 'The 2022 Ukraine Electric Power Attack was a Sandworm Team campaign that used a combination of GOGETTER, Neo-REGEORG, CaddyWiper, and living of the land (LotL) techniques to gain access to a Ukrainian electric utility to send unauthorized commands from their SCADA system.', '["sandworm-team"]', '[{"id":"T1036.004","name":"Masquerade Task or Service","tactic":"stealth"},{"id":"T1053.005","name":"Scheduled Task","tactic":"execution"},{"id":"T1059.001","name":"PowerShell","tactic":"execution"},{"id":"T1095","name":"Non-Application Layer Protocol","tactic":"command-and-control"},{"id":"T1484.001","name":"Group Policy Modification","tactic":"defense-impairment"},{"id":"T1485","name":"Data Destruction","tactic":"impact"},{"id":"T1505.003","name":"Web Shell","tactic":"persistence"},{"id":"T1543.002","name":"Systemd Service","tactic":"persistence"},{"id":"T1570","name":"Lateral Tool Transfer","tactic":"lateral-movement"},{"id":"T1572","name":"Protocol Tunneling","tactic":"command-and-control"}]', '["CaddyWiper"]', '[]', '[]', '[]', '2024-03-27', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
