INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0055', 'quad7-activity', 'Quad7 Activity', 'C0055', 'https://attack.mitre.org/campaigns/C0055', 'Quad7 Activity, also known as CovertNetwork-1658 or the 7777 Botnet, is a network of compromised small office/home office (SOHO) routers. The botnet was initially composed primarily of TP-Link routers and was named Quad7 due to compromised devices exposing TCP port 7777 with the distinctive banner <code>xlogin</code>. Later activity showed a significant increase in compromised Asus routers and the addition of new ports and banners, including TCP port 63256 displaying <code>alogin</code>. Quad7 infrastructure functions as a collection of egress IPs that various China-affiliated threat actors have used to conduct password-spraying and brute-force operations. Microsoft has reported that Storm-0940 leveraged credentials obtained through Quad7 Activity to target organizations in North America and Europe, including government agencies, non-governmental organizations, think tanks, law firms, energy firms, IT providers, and defense industrial base entities.', '[]', '[{"id":"T1027.011","name":"Fileless Storage","tactic":"stealth"},{"id":"T1059.004","name":"Unix Shell","tactic":"execution"},{"id":"T1071.001","name":"Web Protocols","tactic":"command-and-control"},{"id":"T1071.002","name":"File Transfer Protocols","tactic":"command-and-control"},{"id":"T1090.002","name":"External Proxy","tactic":"command-and-control"},{"id":"T1090.003","name":"Multi-hop Proxy","tactic":"command-and-control"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1110.003","name":"Password Spraying","tactic":"credential-access"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1571","name":"Non-Standard Port","tactic":"command-and-control"},{"id":"T1584.005","name":"Botnet","tactic":"resource-development"},{"id":"T1584.008","name":"Network Devices","tactic":"resource-development"},{"id":"T1589.002","name":"Email Addresses","tactic":"reconnaissance"},{"id":"T1665","name":"Hide Infrastructure","tactic":"command-and-control"},{"id":"T1685","name":"Disable or Modify Tools","tactic":"defense-impairment"}]', '["ftp"]', '["CVE-2023-50224","CVE-2025-9377"]', '["Government","Defense","Energy"]', '["Europe","North America"]', '2025-06-04', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
--> statement-breakpoint
INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0053', 'florahox-activity', 'FLORAHOX Activity', 'C0053', 'https://attack.mitre.org/campaigns/C0053', 'FLORAHOX Activity is conducted using a hybrid operational relay box (ORB) network, which combines two types of infrastructure: compromised devices and leased Virtual Private Servers (VPS). The compromised devices include end-of-life routers and IoT devices, while VPS space is commercially leased and managed by ORB network administrators. This hybrid ORB network allows adversaries to proxy and obscure malicious traffic, making the source of the traffic more difficult to trace. The FLORAHOX ORB network has been leveraged by multiple cyber threat actors, including China-nexus actors like ZIRCONIUM. These adversaries conduct espionage campaigns through FLORAHOX Activity, relying on the ORB network''s ability to funnel traffic through Tor nodes, provisioned VPS servers, and compromised routers to obfuscate malicious traffic.', '[]', '[{"id":"T1059","name":"Command and Scripting Interpreter","tactic":"execution"},{"id":"T1059.004","name":"Unix Shell","tactic":"execution"},{"id":"T1090.003","name":"Multi-hop Proxy","tactic":"command-and-control"},{"id":"T1190","name":"Exploit Public-Facing Application","tactic":"initial-access"},{"id":"T1583.003","name":"Virtual Private Server","tactic":"resource-development"},{"id":"T1584.008","name":"Network Devices","tactic":"resource-development"}]', '["Tor"]', '[]', '["Space"]', '[]', '2025-03-25', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
--> statement-breakpoint
INSERT OR REPLACE INTO threat_campaigns (id, slug, name, mitre_id, mitre_url, summary, actor_slugs_json, techniques_json, software_json, cves_json, target_sectors_json, target_regions_json, first_seen, last_seen, updated_at) VALUES ('C0004', 'costaricto-c0004', 'CostaRicto', 'C0004', 'https://attack.mitre.org/campaigns/C0004', 'CostaRicto was a suspected hacker-for-hire cyber espionage campaign that targeted multiple industries worldwide, with a large number being financial institutions. CostaRicto actors targeted organizations in Europe, the Americas, Asia, Australia, and Africa, with a large concentration in South Asia (especially India, Bangladesh, and Singapore), using custom malware, open source tools, and a complex network of proxies and SSH tunnels.', '[]', '[{"id":"T1005","name":"Data from Local System","tactic":"collection"},{"id":"T1046","name":"Network Service Discovery","tactic":"discovery"},{"id":"T1053.005","name":"Scheduled Task","tactic":"execution"},{"id":"T1090.003","name":"Multi-hop Proxy","tactic":"command-and-control"},{"id":"T1105","name":"Ingress Tool Transfer","tactic":"command-and-control"},{"id":"T1133","name":"External Remote Services","tactic":"persistence"},{"id":"T1572","name":"Protocol Tunneling","tactic":"command-and-control"},{"id":"T1583.001","name":"Domains","tactic":"resource-development"},{"id":"T1587.001","name":"Malware","tactic":"resource-development"},{"id":"T1588.002","name":"Tool","tactic":"resource-development"}]', '["CostaBricks","PS1","PowerSploit","PsExec","SombRAT","Tor"]', '[]', '[]', '["Europe","Africa","South Asia"]', '2022-09-15', '2026-07-31', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
--> statement-breakpoint
